#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef enum { TOK_EOF, TOK_NUM, TOK_STR, TOK_OP } TokenType;

typedef struct { TokenType type; int ival; char *sval; } Token;

int next_char(const char **src) {
    if (**src == '\0') return -1;
    return *(*src)++;
}

void unget_char(const char **src, char c) {
    if (c != -1) (*src)--;
}

void error(const char *msg) {
    fprintf(stderr, "Error: %s\n", msg);
    exit(EXIT_FAILURE);
}

Token next_token(const char **src) {
    Token tok; tok.sval = NULL; tok.ival = 0;
    int c;
    while ((c = next_char(src)) != -1 && c == ' ');
    if (c == -1) { tok.type = TOK_EOF; return tok; }
    if (c >= '0' && c <= '9') {
        int val = c - '0';
        while ((c = next_char(src)) != -1 && c >= '0' && c <= '9') val = val*10 + (c - '0');
        unget_char(src, c);
        tok.type = TOK_NUM; tok.ival = val;
        return tok;
    }
    if (c == '"') {
        char *s = malloc(1); s[0] = '\0'; int len = 0;
        while ((c = next_char(src)) != -1 && c != '"') {
            if (c == '\\') {
                c = next_char(src);
                if (c == -1) error("Unterminated string");
                if (c == 'n') c = '\n';
                else if (c == 't') c = '\t';
                else if (c == '\\') c = '\\';
                else if (c == '"') c = '"'; // else keep c
            }
            char *tmp = realloc(s, len+2); if (!tmp) error("Out of memory"); s = tmp;
            s[len++] = c; s[len] = '\0';
        }
        if (c == -1) error("Unterminated string");
        tok.type = TOK_STR; tok.sval = s;
        return tok;
    }
    if (c == '+' || c == '-' || c == '*' || c == '/') {
        tok.type = TOK_OP; tok.ival = c; return tok;
    }
    error("Unexpected character");
    return tok;
}

void print_token(Token t) {
    switch (t.type) {
        case TOK_NUM: printf("NUM(%d)\n", t.ival); break;
        case TOK_STR: printf("STR(\"%s\")\n", t.sval); break;
        case TOK_OP: printf("OP(%c)\n", t.ival); break;
        case TOK_EOF: printf("EOF\n"); break;
    }
}

int main(void) {
    const char *input = "\"a\\\"b\" 123 + \"c\"";
    const char *p = input;
    Token t;
    while ((t = next_token(&p)).type != TOK_EOF) {
        print_token(t);
        if (t.sval) free(t.sval);
    }
    print_token(t);
    return 0;
}

#include <stdio.h>

typedef struct {
    long long num;
    long long den;
} Frac;

// return a/b + c/d, assume result fits in long long
Frac frac_add(Frac a, Frac b) {
    Frac r;
    r.num = a.num * b.den + b.num * a.den;
    r.den = a.den * b.den;
    return r;
}

// return the value of the continued fraction [a0; a1, a2, ..., an]
// using the recurrence from the end
Frac eval_cf(const int *a, int n) {
    Frac f = { a[n], 1 };
    for (int i = n - 1; i >= 0; i--) {
        Frac term = { a[i], 1 };
        f = frac_add(term, (Frac){ f.den, f.num });
    }
    return f;
}

// compute the continued fraction expansion of sqrt(2) up to n terms
// returns the terms in array a, and the length in *len
// a[0] is the integer part, then the periodic part repeats
// (for sqrt(2) it's [1; 2, 2, 2, ...])
void sqrt2_cf(int n, int *a, int *len) {
    if (n <= 0) { *len = 0; return; }
    a[0] = 1;
    if (n == 1) { *len = 1; return; }
    for (int i = 1; i < n; i++) a[i] = 2;
    *len = n;
}

