#include <stdio.h>
#include <stdlib.h>
#include <getopt.h>

#define OPT_VERBOSE 0x01
#define OPT_FORCE   0x02
#define OPT_DRY_RUN 0x04

static int options = 0;
static const char *output_file = NULL;

static void print_usage(const char *prog) {
    fprintf(stderr, "Usage: %s [-v] [-f] [-n] [-o file] input\n", prog);
}

int main(int argc, char **argv) {
    int opt;
    while ((opt = getopt(argc, argv, "vfno:")) != -1) {
        switch (opt) {
            case 'v': options |= OPT_VERBOSE; break;
            case 'f': options |= OPT_FORCE; break;
            case 'n': options |= OPT_DRY_RUN; break;
            case 'o': output_file = optarg; break;
            default: print_usage(argv[0]); return EXIT_FAILURE;
        }
    }
    if (optind >= argc) {
        print_usage(argv[0]);
        return EXIT_FAILURE;
    }
    const char *input = argv[optind];
    if (options & OPT_DRY_RUN) {
        printf("Dry run: %s\n", input);
    } else {
        if (options & OPT_FORCE) {
            printf("Force mode\n");
        }
        if (options & OPT_VERBOSE) {
            printf("Verbose\n");
        }
        if (output_file) {
            printf("Output to %s\n", output_file);
        }
        printf("Processing %s\n", input);
    }
    return EXIT_SUCCESS;
}

