#include <stdio.h>
#include <stdint.h>

#define MOD 1000000007

static uint64_t pow_mod(uint64_t base, uint64_t exp, uint64_t mod) {
    uint64_t result = 1;
    base %= mod;
    while (exp > 0) {
        if (exp & 1) result = (result * base) % mod;
        base = (base * base) % mod;
        exp >>= 1;
    }
    return result;
}

int main(void) {
    uint64_t n = 123456789;
    uint64_t k = 987654321;
    uint64_t sum = 0;
    for (uint64_t i = 0; i < n; ++i) {
        uint64_t term = compute_term(i, k);
        sum = (sum + term) % MOD;
    }
    printf("%llu\n", (unsigned long long)sum);
    return 0;
}

