#include <stdio.h>
#include <string.h>

#define N 15
int dist[N][N];
int dp[1 << N][N];

int solve(int mask, int last) {
    if (mask == (1 << N) - 1) return 0;
    if (dp[mask][last] != -1) return dp[mask][last];
    int best = 1000000000;
    for (int i = 0; i < N; i++) {
        if (!(mask & (1 << i))) {
            int cand = dist[last][i] + solve(mask | (1 << i), i);
            if (cand < best) best = cand;
        }
    }
    return dp[mask][last] = best;
}

int main() {
    // Fill distances for a small graph
    for (int i = 0; i < N; i++)
        for (int j = 0; j < N; j++)
            dist[i][j] = (i == j) ? 0 : ((i * 7 + j * 3) % 13);
    memset(dp, -1, sizeof(dp));
    int start = 0;
    printf("%d\n", solve(1 << start, start));
    return 0;
}

