#define _POSIX_C_SOURCE 200809L
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>

static volatile sig_atomic_t g_signal_received = 0;
static volatile sig_atomic_t g_signal_number = 0;

static void handle_signal(int sig) {
    g_signal_received = 1;
    g_signal_number = sig;
}

int main(int argc, char **argv) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <seconds>\n", argv[0]);
        return 1;
    }

    long seconds = strtol(argv[1], NULL, 10);
    if (seconds <= 0) {
        fprintf(stderr, "Invalid time\n");
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    printf("Waiting for %ld seconds...\n", seconds);
    fflush(stdout);

    int remaining = seconds;
    while (remaining > 0 && !g_signal_received) {
        sleep(1);
        --remaining;
    }

    if (g_signal_received) {
        printf("Interrupted by signal %d\n", g_signal_number);
    } else {
        printf("Completed\n");
    }

    return 0;
}

#include <stdint.h>
#include <stddef.h>
#include <string.h>
#include <stdio.h>

/* Packet header: magic 0xCAFE, version 1, flags bit0=compressed, bit1=encrypted */
#define MAGIC 0xCAFEu
#define VERSION 1u

/* Serialized record: 4-byte header, then payload. */
#pragma pack(push, 1)
typedef struct {
    uint16_t magic;
    uint8_t version;
    uint8_t flags;
    uint32_t payload_len;
    uint8_t data[];
} Packet;
#pragma pack(pop)

/* Fixed offset of the data field in the packed struct */
#define DATA_OFFSET (sizeof(uint16_t) + sizeof(uint8_t) + sizeof(uint8_t) + sizeof(uint32_t))

/* Encode a 32-bit value in big-endian order into buf. */
static void put_be32(uint8_t *buf, uint32_t val) {
    buf[0] = (uint8_t)(val >> 24);
    buf[1] = (uint8_t)(val >> 16);
    buf[2] = (uint8_t)(val >> 8);
    buf[3] = (uint8_t)val;
}

/* Decode a big-endian 32-bit value from buf. */
static uint32_t get_be32(const uint8_t *buf) {
    return ((uint32_t)buf[0] << 24) | ((uint32_t)buf[1] << 16) |
           ((uint32_t)buf[2] << 8) | (uint32_t)buf[3];
}

/* Validate a packet header: correct magic, version, and payload length. */
static int validate_header(const Packet *pkt, size_t avail) {
    if (pkt->magic != MAGIC || pkt->version != VERSION) return 0;
    if (pkt->payload_len > avail - DATA_OFFSET) return 0;
    return 1;
}

/* Serialize a record: header + payload (payload is copied as-is). */
static size_t serialize_record(uint8_t *out, size_t out_cap,
                               uint8_t flags, const uint8_t *payload, size_t payload_len) {
    if (out_cap < DATA_OFFSET + payload_len) return 0;
    Packet *pkt = (Packet *)out;
    pkt->magic = MAGIC;
    pkt->version = VERSION;
    pkt->flags = flags;
    pkt->payload_len = (uint32_t)payload_len;
    if (payload_len > 0) memcpy(pkt->data, payload, payload_len);
    return DATA_OFFSET + payload_len;
}

/*
 * Deserialize a record from in[0..in_len-1].
 * Returns number of bytes consumed, or 0 on error.
 * Stores the payload pointer (points into in) and its length.
 */
static size_t deserialize_record(const uint8_t *in, size_t in_len,
                                 uint8_t *flags_out, const uint8_t **payload_out, size_t *payload_len_out) {
    if (in_len < DATA_OFFSET) return 0;
    const Packet *pkt = (const Packet *)in;
    if (!validate_header(pkt, in_len)) return 0;
    *flags_out = pkt->flags;
    *payload_len_out = pkt->payload_len;
    *payload_out = pkt->data;
    return DATA_OFFSET + pkt->payload_len;
}

/* Extract the two flag bits from a flags byte. */
static uint8_t get_flags_bits(uint8_t flags) {
    return flags & 0x03;
}

