    size_t written = serialize_record(buffer, sizeof(buffer), 0x03, payload, sizeof(payload));
    if (written == 0) return 1;
    uint8_t flags;
    const uint8_t *decoded_payload;
    size_t decoded_len;
    size_t consumed = deserialize_record(buffer, written, &flags, &decoded_payload, &decoded_len);
    if (consumed != written) return 2;
    if (get_flags_bits(flags) != 0x03) return 3;
    if (decoded_len != sizeof(payload)) return 4;
