/* Pack a 16-bit value into one byte: high nibble is the value, low nibble is a checksum. */
static uint8_t pack_byte(uint8_t value) {
    uint8_t high = value >> 4;
    uint8_t low = (value & 0x0F);
    uint8_t checksum = (high ^ low) & 0x0F;
    return (uint8_t)((high << 4) | checksum);
}

/* Unpack, verifying checksum. Returns 1 if valid, 0 otherwise. */
static int unpack_byte(uint8_t packed, uint8_t *value) {
    uint8_t high = packed >> 4;
    uint8_t low = packed & 0x0F;
    uint8_t checksum = (high ^ low) & 0x0F;
    if (checksum != (packed & 0x0F)) return 0;
    *value = (uint8_t)((high << 4) | (low & 0x0F));
    return 1;
}

