#include <stdio.h>
#include <string.h>
#include <stdlib.h>

typedef enum { NUM, PLUS, MINUS, MUL, LP, RP, END } TokType;
typedef struct { TokType type; int val; } Token;

Token tokens[64]; int tok_count = 0; int pos = 0;

void add_token(TokType t, int v) { tokens[tok_count].type = t; tokens[tok_count].val = v; tok_count++; }

void tokenize(const char *s) {
    tok_count = 0; pos = 0;
    const char *p = s;
    while (*p) {
        if (*p == ' ') { p++; continue; }
        if (*p >= '0' && *p <= '9') { int v = 0; while (*p >= '0' && *p <= '9') { v = v*10 + (*p-'0'); p++; } add_token(NUM, v); continue; }
        switch (*p) {
            case '+': add_token(PLUS, 0); break;
            case '-': add_token(MINUS, 0); break;
            case '*': add_token(MUL, 0); break;
            case '(': add_token(LP, 0); break;
            case ')': add_token(RP, 0); break;
            default: exit(1);
        }
        p++;
    }
    add_token(END, 0);
}

Token cur;
void next() { cur = tokens[pos++]; }
int accept(TokType t) { if (cur.type == t) { next(); return 1; } return 0; }
int expect(TokType t) { if (accept(t)) return 1; exit(1); }

int expr();

int factor() {
    if (accept(NUM)) return cur.val;
    if (accept(LP)) { int v = expr(); expect(RP); return v; }
    exit(1);
}

int term() {
    int v = factor();
    while (1) {
        if (accept(MUL)) { v *= factor(); continue; }
        break;
    }
    return v;
}

int expr() {
    int v = term();
    while (1) {
        if (accept(PLUS)) { v += term(); continue; }
        if (accept(MINUS)) { v -= term(); continue; }
        break;
    }
    return v;
}

int parse(const char *s) {
    tokenize(s);
    next();
    int v = expr();
    if (cur.type != END) exit(1);
    return v;
}

int main() {
    const char *tests[] = {"1 + 2 * 3", "(1 + 2) * 3", "10 - 4 - 3", "7"};
    for (int i = 0; i < 4; i++) {
        int r = evaluate(tests[i]);
        printf("%s = %d\n", tests[i], r);
    }
    return 0;
}

