#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int key;
    int height;
    struct Node *left, *right;
} Node;

int max(int a, int b) { return a > b ? a : b; }

int height(Node *n) { return n ? n->height : 0; }

int balance(Node *n) { return n ? height(n->left) - height(n->right) : 0; }

Node* newNode(int key) {
    Node* n = (Node*)malloc(sizeof(Node));
    n->key = key; n->height = 1; n->left = n->right = NULL;
    return n;
}

Node* rightRotate(Node *y) {
    Node *x = y->left;
    Node *T2 = x->right;
    x->right = y;
    y->left = T2;
    y->height = 1 + max(height(y->left), height(y->right));
    x->height = 1 + max(height(x->left), height(x->right));
    return x;
}

Node* leftRotate(Node *x) {
    Node *y = x->right;
    Node *T2 = y->left;
    y->left = x;
    x->right = T2;
    x->height = 1 + max(height(x->left), height(x->right));
    y->height = 1 + max(height(y->left), height(y->right));
    return y;
}

Node* insert(Node* node, int key) {
    if (!node) return newNode(key);
    if (key < node->key)
        node->left = insert(node->left, key);
    else if (key > node->key)
        node->right = insert(node->right, key);
    else
        return node;
    node->height = 1 + max(height(node->left), height(node->right));
    int bal = balance(node);
    if (bal > 1 && key < node->left->key)
        return rightRotate(node);
    if (bal < -1 && key > node->right->key)
        return leftRotate(node);
    if (bal > 1 && key > node->left->key) {
        node->left = leftRotate(node->left);
        return rightRotate(node);
    }
    if (bal < -1 && key < node->right->key) {
        node->right = rightRotate(node->right);
        return leftRotate(node);
    }
    return node;
}

void inorder(Node* root, int *arr, int *idx) {
    if (!root) return;
    inorder(root->left, arr, idx);
    arr[(*idx)++] = root->key;
    inorder(root->right, arr, idx);
}

int main() {
    int keys[] = {10, 20, 30, 40, 50, 25};
    Node *root = NULL;
    for (int i = 0; i < 6; i++) root = insert(root, keys[i]);
    int sorted[6];
    int idx = 0;
    inorder(root, sorted, &idx);
    for (int i = 0; i < 6; i++) printf("%d ", sorted[i]);
    printf("\n");
    return 0;
}

#include <stdint.h>
#include <stdio.h>

#define HEADER_MAGIC 0xDEADBEEF
#define MAX_PAYLOAD 256

typedef struct {
    uint32_t magic;
    uint16_t version;
    uint16_t flags;      // bit 0: compressed, bit 1: encrypted
    uint32_t sequence;
} __attribute__((packed)) header_t;

void print_hex(const uint8_t *buf, size_t len) {
    for (size_t i = 0; i < len; ++i) printf("%02x", buf[i]);
    printf("\n");
}

// Validate the header and extract the payload size.
// Returns 0 on success, -1 on invalid magic or version.
int parse_packet(const uint8_t *packet, size_t len) {
    if (len < sizeof(header_t)) return -1;
    header_t hdr;
    __builtin_memcpy(&hdr, packet, sizeof(hdr));

    if (hdr.magic != HEADER_MAGIC || hdr.version != 1) return -1;

    uint16_t flags = hdr.flags;
    size_t payload_len = len - sizeof(header_t);
    if (payload_len > MAX_PAYLOAD) return -1;

    // Payload starts right after the header.
    const uint8_t *payload = packet + sizeof(header_t);

    // Process flags and payload.
    if (flags & 0x1) {
        // compressed: assume simple XOR with 0xAA for demo
        for (size_t i = 0; i < payload_len; ++i) {
            ((uint8_t *)payload)[i] ^= 0xAA;
        }
    }
    if (flags & 0x2) {
        // encrypted: assume ROT13 for demo
        for (size_t i = 0; i < payload_len; ++i) {
            uint8_t b = ((uint8_t *)payload)[i];
            if (b >= 'a' && b <= 'z') b = (b - 'a' + 13) % 26 + 'a';
            else if (b >= 'A' && b <= 'Z') b = (b - 'A' + 13) % 26 + 'A';
            ((uint8_t *)payload)[i] = b;
        }
    }

    // Verify sequence number is even (a simplified check)
    if (hdr.sequence % 2 != 0) return -1;

    // Now extract the actual payload length from the last 2 bytes of the payload
    // (they store a 16-bit length in little-endian).
    if (payload_len < 2) return -1;
    uint16_t actual_len = payload[payload_len-2] | (payload[payload_len-1] << 8);
    if (actual_len > payload_len - 2) return -1;

    // Print the actual payload bytes.
    printf("Payload (%u bytes): ", actual_len);
    print_hex(payload, actual_len);
    return 0;
};

