#include <stdio.h>
#include <string.h>
#include <ctype.h>

enum { MAX_TOKENS = 64, MAX_LEN = 64 };
typedef struct { char text[MAX_LEN]; int type; } Token;
enum { T_ID, T_NUM, T_OP, T_STR, T_END };

int classify(const char *s) {
    if (isdigit(s[0])) return T_NUM;
    if (isalpha(s[0]) || s[0]=='_') return T_ID;
    if (strchr("+-*/", s[0])) return T_OP;
    if (s[0]=='"') return T_STR;
    return T_END;
}

int tokenize(char *line, Token *tokens) {
    int n = 0;
    char *p = line;
    while (*p) {
        while (*p && isspace((unsigned char)*p)) p++;
        if (!*p) break;
        if (*p=='"') {
            char *q = p+1;
            while (*q && *q!='"') q++;
            if (*q=='"') { q++; } else return -1;
            snprintf(tokens[n].text, MAX_LEN, "%.*s", (int)(q-p), p);
            tokens[n].type = T_STR;
            n++; p = q;
        } else {
            char *q = p+1;
            while (*q && !isspace((unsigned char)*q)) q++;
            snprintf(tokens[n].text, MAX_LEN, "%.*s", (int)(q-p), p);
            tokens[n].type = classify(tokens[n].text);
            n++; p = q;
        }
        if (n >= MAX_TOKENS) return -2;
    }
    return n;
}

int parse(Token *tokens, int count) {
    int pos = 0;
    int result = 0;
    int expect_operand = 1;
    int pending_op = 0;
    while (pos < count && tokens[pos].type != T_END) {
        Token t = tokens[pos];
        if (expect_operand) {
            if (t.type == T_NUM) {
                result = atoi(t.text);
                expect_operand = 0;
                pos++;
            } else if (t.type == T_OP && strcmp(t.text, "-")==0) {
                pending_op = 1;
                pos++;
            } else return -3;
        } else {
            if (t.type == T_OP) {
                if (strcmp(t.text, "+")==0 || strcmp(t.text, "-")==0 || strcmp(t.text, "*")==0 || strcmp(t.text, "/")==0) {
                    pending_op = (t.text[0]=='-') ? 1 : 0;
                    pos++;
                    expect_operand = 1;
                } else return -4;
            } else return -5;
        }
    }
    if (expect_operand) return -6;
    return pending_op ? -result : result;
}

