#include <stdint.h>
#include <string.h>

#define MAX_BITS 32

// Sort array of uint32_t in-place using LSD radix sort.
// The sort is stable, but we only need the final order.
void radix_sort(uint32_t *arr, size_t n) {
    // Number of buckets per pass: 256 (8 bits per pass)
    const unsigned BUCKETS = 256;
    const unsigned PASSES = 4; // 32/8

    // Temporary buffer for counting sort
    uint32_t *tmp = (uint32_t*)malloc(n * sizeof(uint32_t));
    if (!tmp) return; // handle allocation failure

    // For each pass, process 8 bits starting from least significant
    for (unsigned pass = 0; pass < PASSES; ++pass) {
        unsigned shift = pass * 8;
        // Count occurrences
        size_t count[BUCKETS] = {0};
        for (size_t i = 0; i < n; ++i) {
            unsigned byte = (arr[i] >> shift) & 0xFF;
            count[byte]++;
        }
        // Convert counts to starting indices (prefix sum)
        size_t start[BUCKETS];
        size_t sum = 0;
        for (unsigned b = 0; b < BUCKETS; ++b) {
            start[b] = sum;
            sum += count[b];
        }
        // Distribute elements into tmp
        for (size_t i = 0; i < n; ++i) {
            unsigned byte = (arr[i] >> shift) & 0xFF;
            tmp[start[byte]++] = arr[i];
        }
        // Copy back
        memcpy(arr, tmp, n * sizeof(uint32_t));
    }
    free(tmp);
}

// Compute the maximum value in the array (helper for later)
static uint32_t max_value(const uint32_t *arr, size_t n) {
    if (n == 0) return 0;
    uint32_t m = arr[0];
    for (size_t i = 1; i < n; ++i) {
        if (arr[i] > m) m = arr[i];
    }
    return m;
}

// Sort an array of uint32_t in ascending order.
// This is the main entry point that selects the algorithm based on data.
void sort_u32(uint32_t *arr, size_t n) {
    if (n < 2) return;
    uint32_t maxv = max_value(arr, n);
    // For small max values, use counting sort directly (faster)
    if (maxv < 65536) {
        // Simple counting sort for 16-bit range
        size_t count[65536] = {0};
        for (size_t i = 0; i < n; ++i) count[arr[i]]++;
        size_t idx = 0;
        for (uint32_t v = 0; v < 65536; ++v) {
            while (count[v]--) arr[idx++] = v;
        }
        return;
    }
    // Otherwise use radix sort
    radix_sort(arr, n);
}

