const maxWorkers = 3
const maxQueue = 10

var wg sync.WaitGroup

func worker(ctx context.Context, id int, jobs <-chan packet, results chan<- packet) {
	defer wg.Done()
	for {
		select {
		case <-ctx.Done():
			return
		case p, ok := <-jobs:
			if !ok {
				return
			}
			// simulate processing
			time.Sleep(time.Duration(p.seq%3) * 10 * time.Millisecond)
			results <- p
		}
	}
}

func main() {
	ctx, cancel := context.WithTimeout(context.Background(), 100*time.Millisecond)
	defer cancel()

	jobs := make(chan packet, maxQueue)
	results := make(chan packet, maxQueue)

	// start workers
	for i := 0; i < maxWorkers; i++ {
		wg.Add(1)
		go worker(ctx, i, jobs, results)
	}

	// produce packets in order
	for i := 0; i < 50; i++ {
		select {
		case <-ctx.Done():
			break
		default:
			jobs <- packet{seq: i, data: fmt.Sprintf("packet-%d", i)}
		}
	}

	// close jobs to signal no more input
	close(jobs)

	// collect results until context done or results closed
	go func() {
		<-ctx.Done()
		close(results)
	}()

	// wait for workers to finish
	wg.Wait()
	close(results)

	// process results in order of seq
	collected := make([]packet, 0)
	for p := range results {
		collected = append(collected, p)
	}

	// sort by seq (since workers may reorder)
	sortBySeq(collected)

