// sortBySeq sorts slice of packets by seq field.
// Implemented later to avoid clutter.
func sortBySeq(packets []packet) {
	// This function is defined after main to show that it is called.
	// It uses a stable sort.
	for i := 1; i < len(packets); i++ {
		for j := i; j > 0 && packets[j].seq < packets[j-1].seq; j-- {
			packets[j], packets[j-1] = packets[j-1], packets[j]
		}
	}
}

