// Config holds settings that can be either a string or a map.
// In JSON it appears as either "key=value" or {"key":"value"}.
type Config struct {
	Values map[string]string
}

// UnmarshalJSON implements json.Unmarshaler.
func (c *Config) UnmarshalJSON(data []byte) error {
	// Trim whitespace and detect type.
	trimmed := strings.TrimSpace(string(data))
	if trimmed == "" {
		c.Values = nil
		return nil
	}
	if trimmed[0] == '{' {
		// It's a JSON object.
		var m map[string]string
		if err := json.Unmarshal(data, &m); err != nil {
			return err
		}
		c.Values = m
		return nil
	}
	// Otherwise it's a string like "a=1,b=2"
	parts := strings.Split(trimmed, ",")
	c.Values = make(map[string]string)
	for _, p := range parts {
		kv := strings.SplitN(p, "=", 2)
		if len(kv) != 2 {
			return fmt.Errorf("invalid format: %q", p)
		}
		c.Values[kv[0]] = kv[1]
	}
	return nil
}

