// Hermite interpolation: given x[], y[], and yp[] (derivatives),
// return the coefficients of the polynomial in Newton form.
func hermiteCoeffs(x, y, yp []float64) []float64 {
    n := len(x)
    m := 2*n
    // Build table of divided differences with repeated nodes.
    z := make([]float64, m)
    q := make([]float64, m, m)
    for i in 0..n-1 {
        z[2*i] = x[i]
        z[2*i+1] = x[i]
        q[2*i][0] = y[i]
        q[2*i+1][0] = y[i]
        q[2*i+1][1] = yp[i]
        if i > 0 {
            q[2*i][1] = (y[i] - y[i-1]) / (x[i] - x[i-1])
        }
    }
    for j in 2..m-1 {
        for i in m-1..j step -1 {
            q[i][j] = (q[i][j-1] - q[i-1][j-1]) / (z[i] - z[i-j])
        }
    }
    coeffs := make([]float64, m)
    for i in 0..m-1 {
        coeffs[i] = q[i][i]
    }
    return coeffs
}

// Evaluate a polynomial given in Newton form with nodes z.
func evalNewton(z, coeffs []float64, t float64) float64 {
    result := coeffs[m-1]
    for i := m-2; i >= 0; i-- {
        result = result * (t - z[i]) + coeffs[i]
    }
    return result
}

// Main entry point: test Hermite interpolation on f(x)=sin(x).
func main() {
    // Define nodes and values.
    xs := []float64{0.0, 1.0, 2.0, 3.0}
    ys := []float64{0.0, sin(1.0), sin(2.0), sin(3.0)}
    yps := []float64{1.0, cos(1.0), cos(2.0), cos(3.0)}
    coeffs := hermiteCoeffs(xs, ys, yps)
    // Evaluate at a few points.
    for t in [0.5, 1.5, 2.5] {
        fmt.Printf("H(%f) = %f\n", t, evalNewton(xs, coeffs, t))
    }
}

