#include <pthread.h>
#include <stdatomic.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int *queue;
    int capacity;
    int head;
    int tail;
    int count;
    pthread_mutex_t lock;
    pthread_cond_t not_empty;
    pthread_cond_t not_full;
    _Atomic bool shutdown;
} bounded_buffer_t;

void buffer_init(bounded_buffer_t *bb, int cap) {
    bb->queue = malloc(cap * sizeof(int));
    bb->capacity = cap;
    bb->head = 0;
    bb->tail = 0;
    bb->count = 0;
    pthread_mutex_init(&bb->lock, NULL);
    pthread_cond_init(&bb->not_empty, NULL);
    pthread_cond_init(&bb->not_full, NULL);
    atomic_store(&bb->shutdown, false);
}

void buffer_destroy(bounded_buffer_t *bb) {
    free(bb->queue);
    pthread_mutex_destroy(&bb->lock);
    pthread_cond_destroy(&bb->not_empty);
    pthread_cond_destroy(&bb->not_full);
}

static void buffer_put(bounded_buffer_t *bb, int item) {
    pthread_mutex_lock(&bb->lock);
    while (bb->count == bb->capacity) {
        pthread_cond_wait(&bb->not_full, &bb->lock);
    }
    bb->queue[bb->tail] = item;
    bb->tail = (bb->tail + 1) % bb->capacity;
    bb->count++;
    pthread_cond_signal(&bb->not_empty);
    pthread_mutex_unlock(&bb->lock);
}

static int buffer_get(bounded_buffer_t *bb, bool *shutdown) {
    pthread_mutex_lock(&bb->lock);
    while (bb->count == 0 && !atomic_load(&bb->shutdown)) {
        pthread_cond_wait(&bb->not_empty, &bb->lock);
    }
    if (bb->count == 0 && atomic_load(&bb->shutdown)) {
        *shutdown = true;
        pthread_mutex_unlock(&bb->lock);
        return 0;
    }
    int item = bb->queue[bb->head];
    bb->head = (bb->head + 1) % bb->capacity;
    bb->count--;
    pthread_cond_signal(&bb->not_full);
    pthread_mutex_unlock(&bb->lock);
    *shutdown = false;
    return item;
}

void buffer_shutdown(bounded_buffer_t *bb) {
    pthread_mutex_lock(&bb->lock);
    atomic_store(&bb->shutdown, true);
    pthread_cond_broadcast(&bb->not_empty);
    pthread_mutex_unlock(&bb->lock);
}

#define NUM_THREADS 4
#define NUM_ITEMS 100

typedef struct {
    bounded_buffer_t *bb;
    int id;
} worker_arg_t;

static void *worker(void *arg) {
    worker_arg_t *wa = (worker_arg_t *)arg;
    bounded_buffer_t *bb = wa->bb;
    int id = wa->id;
    bool shutdown = false;
    while (!shutdown) {
        int item = buffer_get(bb, &shutdown);
        if (shutdown) break;
        printf("Worker %d got %d\n", id, item);
    }
    return NULL;
}

int main(void) {
    bounded_buffer_t bb;
    buffer_init(&bb, 10);
    pthread_t threads[NUM_THREADS];
