package main

import "fmt"

// gcd computes the greatest common divisor of a and b.
func gcd(a, b int) int {
	for b != 0 {
		a, b = b, a%b
	}
	return a
}

// phi computes Euler's totient function for n.
func phi(n int) int {
	result := n
	p := 2
	for p*p <= n {
		if n%p == 0 {
			for n%p == 0 {
				n /= p
			}
			result -= result / p
		}
		p++
	}
	if n > 1 {
		result -= result / n
	}
	return result
}

// modMul computes (a * b) % mod using repeated doubling to avoid overflow.
func modMul(a, b, mod int) int {
	res := 0
	a %= mod
	for b > 0 {
		if b&1 == 1 {
			res = (res + a) % mod
		}
		a = (a * 2) % mod
		b >>= 1
	}
	return res
}

// modExp computes (base^exp) % mod using binary exponentiation.
func modExp(base, exp, mod int) int {
	result := 1
	base %= mod
	for exp > 0 {
		if exp&1 == 1 {
			result = modMul(result, base, mod)
		}
		base = modMul(base, base, mod)
		exp >>= 1
	}
	return result
}

func main() {
	// Test the implementation with a known case.
	n := 221
	e := 7
	// e and phi(n) are coprime
	phiN := phi(n)
	if gcd(e, phiN) != 1 {
		panic("invalid exponent")
	}
	// Find modular inverse of e modulo phiN using extended Euclidean algorithm.
	d := modInverse(e, phiN)
	// Encrypt and decrypt a message.
	msg := 42
	cipher := modExp(msg, e, n)
	decrypted := modExp(cipher, d, n)
