import (
	"context"
	"fmt"
	"net"
	"os"
	"time"
)

const (
	listenAddr = "127.0.0.1:0"
	maxConns   = 3
	timeout    = 2 * time.Second
)

func handleConn(ctx context.Context, conn net.Conn, id int) {
	defer conn.Close()
	select {
	case <-ctx.Done():
		fmt.Printf("conn %d closed by context\n", id)
	case <-time.After(timeout):
		fmt.Printf("conn %d idle timeout\n", id)
	}
}

func main() {
	ln, err := net.Listen("tcp", listenAddr)
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	defer ln.Close()

	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	connCh := make(chan net.Conn, maxConns)
	go func() {
		for {
			conn, err := ln.Accept()
			if err != nil {
				return
			}
			select {
			case connCh <- conn:
			case <-ctx.Done():
				conn.Close()
				return
			}
		}
	}()

	for i := 0; i < maxConns; i++ {
		select {
		case conn := <-connCh:
			go handleConn(ctx, conn, i)
		case <-ctx.Done():
			return
		}
	}
	fmt.Println("accepted max connections, waiting for timeout")
	time.Sleep(timeout + 100*time.Millisecond)
	fmt.Println("done")
}

