package main

import (
	"context"
	"errors"
	"fmt"
	"net"
	"sync"
	"time"
)

const (
	maxIdle = 5
	maxLifetime = time.Minute
	dialTimeout = 3 * time.Second
)

var (
	mu sync.Mutex
	idle = make([]net.Conn, 0, maxIdle)
	numOpen int
	maxOpen = 10
)

func dial() (net.Conn, error) {
	return net.DialTimeout("tcp", "example.com:80", dialTimeout)
}

func get(ctx context.Context) (net.Conn, error) {
	mu.Lock()
	for len(idle) > 0 {
		c := idle[len(idle)-1]
		idle = idle[:len(idle)-1]
		mu.Unlock()
		if time.Since(c.(*conn).created) < maxLifetime {
			return c, nil
		}
		c.Close()
		mu.Lock()
	}
	if numOpen >= maxOpen {
		mu.Unlock()
		return nil, errors.New("max open connections")
	}
	numOpen++
	mu.Unlock()
	c, err := dial()
	if err != nil {
		mu.Lock()
		numOpen--
		mu.Unlock()
		return nil, err
	}
	return &conn{Conn: c, created: time.Now()}, nil
}

func put(c net.Conn) {
	cc := c.(*conn)
	mu.Lock()
	if len(idle) < maxIdle && time.Since(cc.created) < maxLifetime {
		idle = append(idle, c)
	} else {
		c.Close()
	}
	numOpen--
	mu.Unlock()
}

type conn struct {
	net.Conn
	created time.Time
}

func main() {
	ctx := context.Background()
	c1, _ := get(ctx)
	fmt.Fprintf(c1, "GET / HTTP/1.0\r\n\r\n")
	buf := make([]byte, 1024)
	c1.Read(buf)
	put(c1)

	c2, _ := get(ctx)
	fmt.Fprintf(c2, "GET / HTTP/1.0\r\n\r\n")
	c2.Read(buf)
	put(c2)

	c3, _ := get(ctx)
	fmt.Fprintf(c3, "GET / HTTP/1.0\r\n\r\n")
	c3.Read(buf)
	put(c3)

	fmt.Println("done")
}

