import (
	"fmt"
	"math"
)

// Simpson's rule for numerical integration
func simpson(f func(float64) float64, a, b float64, n int) float64 {
	h := (b - a) / float64(n)
	sum := f(a) + f(b)
	for i := 1; i < n; i++ {
		x := a + float64(i)*h
		if i%2 == 1 {
			sum += 4*f(x)
		} else {
			sum += 2*f(x)
		}
	}
	return sum * h / 3
}

// midpoint rule for numerical integration
func midpoint(f func(float64) float64, a, b float64, n int) float64 {
	h := (b - a) / float64(n)
	sum := 0.0
	for i := 0; i < n; i++ {
		x := a + (float64(i)+0.5)*h
		sum += f(x)
	}
	return sum * h
}

func main() {
	// Define a function to integrate: f(x) = sin(x)
	f := func(x float64) float64 { return math.Sin(x) }

	// Compute approximations using different methods
	approxSimpson := simpson(f, 0, math.Pi, 100)
	approxMidpoint := midpoint(f, 0, math.Pi, 100)

	// Expected exact integral: -cos(pi) - (-cos(0)) = 2
	exact := 2.0
	fmt.Printf("Simpson: %.6f, error: %.6f\n", approxSimpson, math.Abs(approxSimpson-exact))
	fmt.Printf("Midpoint: %.6f, error: %.6f\n", approxMidpoint, math.Abs(approxMidpoint-exact))

	// Compare errors
	simpsonErr := math.Abs(approxSimpson - exact)
	midpointErr := math.Abs(approxMidpoint - exact)
	fmt.Printf("Simpson error < midpoint error: %v\n", simpsonErr < midpointErr)

	// Use a higher-order method: composite trapezoidal with Richardson extrapolation
	// We'll compute trapezoidal for n and 2n, then extrapolate: R = (4*T(2n) - T(n))/3
	// (This is Simpson's rule actually, but we'll implement it manually)
	trap := func(f func(float64) float64, a, b float64, n int) float64 {
		h := (b - a) / float64(n)
		sum := (f(a) + f(b)) / 2
		for i := 1; i < n; i++ {
			sum += f(a + float64(i)*h)
		}
		return sum * h
	}

	n := 100
	trap1 := trap(f, 0, math.Pi, n)
	trap2 := trap(f, 0, math.Pi, 2*n)
	extrapolated := (4*trap2 - trap1) / 3
	fmt.Printf("Extrapolated: %.6f, error: %.6f\n", extrapolated, math.Abs(extrapolated-exact))
}

