const maxDepth = 3

type Resource struct {
	name string
}

func (r *Resource) Close() error {
	if r.name == "bad" {
		return errors.New("close failed: " + r.name)
	}
	return nil
}

func openResource(name string) (*Resource, error) {
	if name == "" {
		return nil, errors.New("empty name")
	}
	return &Resource{name: name}, nil
}

func process(depth int) (err error) {
	if depth > maxDepth {
		return errors.New("depth exceeded")
	}
	res, err := openResource(fmt.Sprintf("res-%d", depth))
	if err != nil {
		return fmt.Errorf("open at depth %d: %w", depth, err)
	}
	defer func() {
		if cerr := res.Close(); cerr != nil {
			err = errors.Join(err, fmt.Errorf("close at depth %d: %w", depth, cerr))
		}
	}()
	if depth == maxDepth {
		return nil
	}
	err = process(depth + 1)
	if err != nil {
		return fmt.Errorf("recurse at depth %d: %w", depth, err)
	}
	return nil
}

func main() {
	err := process(0)
	if err != nil {
		fmt.Println("failed:", err)
		os.Exit(1)
	}
	fmt.Println("success")
}

