	baseDelay  = 10 * time.Millisecond
)

type transientError struct {
	op  string
	err error
}

func (e *transientError) Error() string {
	return fmt.Sprintf("%s: %v", e.op, e.err)
}

func (e *transientError) Unwrap() error {
	return e.err
}

func isTransient(err error) bool {
	var te *transientError
	return errors.As(err, &te)
}

func doWork(ctx context.Context, id int) error {
	if ctx.Err() != nil {
		return &transientError{op: "doWork", err: ctx.Err()}
	}
	if id%2 == 0 {
		return &transientError{op: "doWork", err: errors.New("simulated failure")}
	}
	return nil
}

func main() {
	var wg sync.WaitGroup
	ctx, cancel := context.WithTimeout(context.Background(), 50*time.Millisecond)
	defer cancel()

	for i := 0; i < 5; i++ {
		wg.Add(1)
		go func(id int) {
			defer wg.Done()
			err := processWithRetry(ctx, id)
			if err != nil {
				fmt.Printf("worker %d failed: %v\n", id, err)
			} else {
				fmt.Printf("worker %d succeeded\n", id)
			}
		}(i)
	}
	wg.Wait()
}

