			toks = append(toks, token{"num", s[i:j]})
			i = j
		case s[i] == '+' || s[i] == '-' || s[i] == '*' || s[i] == '/' || s[i] == '(' || s[i] == ')':
			toks = append(toks, token{"op", string(s[i])})
			i++
		default:
			panic("bad token")
		}
	}
	return toks
}

// expr parses an expression and returns its integer value.
// It consumes tokens from *pos and updates it.
func expr(toks []token, pos *int) int {
	// handle addition and subtraction
	left := term(toks, pos)
	for *pos < len(toks) && (toks[*pos].val == "+" || toks[*pos].val == "-") {
		op := toks[*pos].val
		*pos++
		right := term(toks, pos)
		if op == "+" {
			left += right
		} else {
			left -= right
		}
	}
	return left
}

// term parses a term (multiplication and division) and returns its value.
func term(toks []token, pos *int) int {
	left := factor(toks, pos)
	for *pos < len(toks) && (toks[*pos].val == "*" || toks[*pos].val == "/") {
		op := toks[*pos].val
		*pos++
		right := factor(toks, pos)
		if op == "*" {
			left *= right
		} else {
			left /= right
		}
	}
	return left
}

// factor parses a factor: either a number or a parenthesized expression.
func factor(toks []token, pos *int) int {
	if toks[*pos].val == "(" {
		*pos++
		val := expr(toks, pos)
		if toks[*pos].val != ")" {
			panic("missing closing paren")
		}
		*pos++
		return val
	}
	n, _ := strconv.Atoi(toks[*pos].val)
	*pos++
	return n
}

func main() {
	s := "3 + 5 * ( 10 - 2 ) / 4 - 1"
	toks := tokenize(s)
	pos := 0
	result := expr(toks, &pos)
	fmt.Println(result)
}

