// factorial computes n! mod 1e9+7
func factorial(n int) int {
	mod := 1000000007
	res := 1
	for i := 2; i <= n; i++ {
		res = (res * i) % mod
	}
	return res
}

// modPow computes base^exp mod 1e9+7
func modPow(base, exp int) int {
	mod := 1000000007
	res := 1
	for exp > 0 {
		if exp%2 == 1 {
			res = (res * base) % mod
		}
		base = (base * base) % mod
		exp /= 2
	}
	return res
}

// inverse computes modular inverse of a under mod 1e9+7
func inverse(a int) int {
	return modPow(a, 1000000005)
}

// nCr computes binomial coefficient n choose r modulo mod
func nCr(n, r int) int {
	if r < 0 || r > n {
		return 0
	}
	return factorial(n) * inverse(factorial(r)) % 1000000007 * inverse(factorial(n-r)) % 1000000007
}

