const maxWorkers = 3
const jobCount = 10

type job struct {
	id int
}

type result struct {
	id   int
	info string
}

func process(ctx context.Context, id int) (*result, error) {
	select {
	case <-ctx.Done():
		return nil, ctx.Err()
	case <-time.After(50 * time.Millisecond):
		return &result{id: id, info: fmt.Sprintf("processed %d", id)}, nil
	}
}

func main() {
	ctx, cancel := context.WithTimeout(context.Background(), 200*time.Millisecond)
	defer cancel()

	jobs := make(chan job)
	results := make(chan *result)
	var wg sync.WaitGroup

	// start workers
	for i := 0; i < maxWorkers; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for j := range jobs {
				res, err := process(ctx, j.id)
				if err != nil {
					continue
				}
				results <- res
			}
		}()
	}

	// send jobs
	go func() {
		for id := 0; id < jobCount; id++ {
			select {
			case jobs <- job{id: id}:
			case <-ctx.Done():
				break
			}
		}
		close(jobs)
	}()

	// collect results
	go func() {
		wg.Wait()
		close(results)
	}()

	// process results
	for res := range results {
		fmt.Println(res.info)
	}
}

