def unreliable_call():
    if random.random() < 0.3:
        raise ConnectionError("transient failure")
    return "success"

@contextmanager
def suppress_exception(exc_type):
    try:
        yield
    except exc_type:
        pass

class RetryExhaustedError(RuntimeError):
    pass

def retry_with_backoff(func, retries=MAX_RETRIES, base_delay=BASE_DELAY, max_delay=MAX_DELAY):
    delay = base_delay
    last_exc = None
    for attempt in range(retries):
        try:
            return func()
        except ConnectionError as exc:
            last_exc = exc
            time.sleep(delay)
            delay = min(delay * 2, max_delay)
    raise RetryExhaustedError(f"Failed after {retries} attempts") from last_exc

def main():
    with suppress_exception(RetryExhaustedError):
        result = retry_with_backoff(unreliable_call)
        print(f"Result: {result}")
    print("Done")

