const maxDepth = 3

// walkDir prints all files under root up to maxDepth.
// It skips symlinks to avoid cycles.
func walkDir(root string, depth int) error {
	if depth > maxDepth {
		return nil
	}

	return filepath.Walk(root, func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return err
		}
		if info.Mode()&os.ModeSymlink != 0 {
			return nil
		}
		if info.IsDir() {
			return nil
		}
		fmt.Println(path)
		return nil
	})
}

