import math

def legendre(n, x):
    if n == 0:
        return 1.0
    if n == 1:
        return x
    return ((2*n - 1)*x*legendre(n-1, x) - (n - 1)*legendre(n-2, x)) / n

def dlegendre(n, x):
    return n * (x*legendre(n, x) - legendre(n-1, x)) / (x*x - 1)

def gauss_legendre_quadrature(f, a, b, n):
    # nodes and weights for n-point Gauss-Legendre on [-1,1]
    nodes = []
    weights = []
    for i in range(n):
        # initial guess: Chebyshev nodes
        x = math.cos(math.pi * (i + 0.75) / (n + 0.5))
        for _ in range(100):
            p = legendre(n, x)
            dp = dlegendre(n, x)
            if abs(p) < 1e-14:
                break
            x -= p / dp
        nodes.append(x)
        w = 2 / ((1 - x*x) * dlegendre(n, x)**2)
        weights.append(w)
    # map from [-1,1] to [a,b]
    scale = (b - a) / 2
    shift = (a + b) / 2
    total = 0
    for x, w in zip(nodes, weights):
        total += w * f(scale * x + shift)
    return scale * total

