import (
	"fmt"
	"time"
)

const workers = 4
const jobsPerWorker = 3

// produce sends numbers 1..N to a channel
func produce(n int, out chan<- int) {
	for i := 1; i <= n; i++ {
		out <- i
	}
	close(out)
}

// consume reads from in, squares, and sends to out
func consume(id int, in <-chan int, out chan<- int) {
	for v := range in {
		out <- v * v
	}
	close(out)
}

func merge(chans ...<-chan int) <-chan int {
	out := make(chan int)
	var wg sync.WaitGroup
	wg.Add(len(chans))
	for _, ch := range chans {
		go func(c <-chan int) {
			defer wg.Done()
			for v := range c {
				out <- v
			}
		}(ch)
	}
	go func() {
		wg.Wait()
		close(out)
	}()
	return out
}

