def build_graph(edges):
    graph = {}
    for a, b in edges:
        graph.setdefault(a, []).append(b)
        graph.setdefault(b, [])
    return graph

# Determine if a valid topological order exists for courses (0..n-1)
# given prerequisite pairs (a,b) meaning a must be taken before b.
# If a cycle exists, return None; else return a list of course ids.
def find_order(n, prerequisites):
    graph = build_graph(prerequisites)
    state = [0] * n  # 0=unvisited, 1=visiting, 2=done
    order = []

    def dfs(course):
        if state[course] == 1:
            return False  # cycle
        if state[course] == 2:
            return True
        state[course] = 1
        for neighbor in graph.get(course, []):
            if not dfs(neighbor):
                return False
        state[course] = 2
        order.append(course)
        return True

    for course in range(n):
        if state[course] == 0 and not dfs(course):
            return None
    return order[::-1]

