from collections import defaultdict

ROOT = Path('/tmp/project')
SIZE_THRESHOLD = 1024 * 1024  # 1 MB

def get_file_sizes(directory):
    """Return a dict mapping file paths to their sizes in bytes."""
    sizes = {}
    for dirpath, _, filenames in os.walk(directory):
        for name in filenames:
            full = Path(dirpath) / name
            try:
                sizes[str(full)] = full.stat().st_size
            except OSError:
                continue
    return sizes

# Build an index of files that are larger than the threshold.
# The index maps each directory to a list of (filename, size) tuples,
# sorted by size descending.
# We only consider files under ROOT, and we need to handle the case
# where a file's path is relative to ROOT.

def index_large_files(root, threshold):
    """Return a dict: directory -> sorted list of (filename, size)."""
    index = defaultdict(list)
    for path, size in get_file_sizes(root).items():
        if size > threshold:
            rel = Path(path).relative_to(root)
            directory = str(rel.parent) if rel.parent != Path('.') else '.'
            index[directory].append((rel.name, size))
    for dirname in index:
        index[dirname].sort(key=lambda x: x[1], reverse=True)
    return dict(index)

# Now we want to print a summary of large files, grouped by directory.
# For each directory, print the directory name and then each file with its size.
# Directories should be processed in alphabetical order.

def print_summary(index):
    """Print a summary of large files per directory."""
    for dirname in sorted(index):
        print(f"Directory: {dirname}")
        for filename, size in index[dirname]:
