const net = require('net');
const MAX_CONNECTIONS = 5;
const CONNECT_TIMEOUT = 2000;

class ConnectionPool {
  constructor(host, port) {
    this.host = host;
    this.port = port;
    this.available = [];
    this.active = new Set();
    this.waiting = [];
    this.maxConnections = MAX_CONNECTIONS;
  }

  _createConnection() {
    const socket = net.createConnection({ host: this.host, port: this.port });
    socket.setTimeout(CONNECT_TIMEOUT);
    return new Promise((resolve, reject) => {
      socket.once('connect', () => {
        socket.removeAllListeners('timeout');
        socket.on('error', (err) => this._handleSocketError(err, socket));
        resolve(socket);
      });
      socket.once('timeout', () => {
        socket.destroy();
        reject(new Error('Connect timeout'));
      });
      socket.once('error', reject);
    });
  }

  _handleSocketError(err, socket) {
    this.active.delete(socket);
    socket.destroy();
    this._notifyWaiters();
  }

  _notifyWaiters() {
    while (this.waiting.length > 0 && this.available.length < this.maxConnections) {
      if (this.active.size + this.available.length >= this.maxConnections) break;
      const resolve = this.waiting.shift();
      this._getConnection().then(resolve).catch(() => {});
    }
  }

  async _getConnection() {
    if (this.available.length > 0) {
      const sock = this.available.pop();
      this.active.add(sock);
      return sock;
    }
    if (this.active.size < this.maxConnections) {
      const sock = await this._createConnection();
      this.active.add(sock);
      return sock;
    }
    return new Promise((resolve, reject) => {
      this.waiting.push(resolve);
      this._notifyWaiters();
    });
  }

  acquire() {
    return this._getConnection();
  }

  release(socket) {
    if (this.active.delete(socket)) {
      if (socket.destroyed) {
        this._notifyWaiters();
      } else {
        socket.removeAllListeners('error');
        socket.on('error', () => {});
        this.available.push(socket);
        this._notifyWaiters();
      }
    }
  }

  close() {
    for (const sock of this.available) sock.destroy();
    for (const sock of this.active) sock.destroy();
    this.available = [];
    this.active.clear();
    this.waiting = [];
  }
}

async function runRequests(pool) {
  const results = [];
  async function request(data) {
    const sock = await pool.acquire();
    try {
      return await new Promise((resolve, reject) => {
        sock.write(data);
        sock.once('data', (chunk) => resolve(chunk.toString().trim()));
        sock.once('error', reject);
      });
    } finally {
      pool.release(sock);
    }
  }
  results.push(await request('PING'));
  results.push(await request('ECHO hello'));
  return results;
}

const pool = new ConnectionPool('localhost', 1234);
runRequests(pool).then(console.log).catch(console.error);
setTimeout(() => pool.close(), 10000);

