    stats = {'count': defaultdict(int), 'size': defaultdict(int)}
    scan_dir(BASE, 0, stats)
    total_files = sum(stats['count'].values())
    total_size = sum(stats['size'].values())
    print(f"Total files: {total_files}")
    print(f"Total size: {total_size} bytes")
    print("\nBreakdown by extension:")
    for ext in sorted(stats['count']):
        count = stats['count'][ext]
        size = stats['size'][ext]
        print(f"{ext or '[none]'}: {count} files, {size} bytes")

if __name__ == '__main__':
    main()

