package main

import (
	"flag"
	"fmt"
	"os"
	"strings"
)

// allowedExtensions defines the only file types the tool accepts.
var allowedExtensions = map[string]bool{
	".go":  true,
	".txt": true,
}

// maxFileSize is the maximum allowed size in bytes.
const maxFileSize = 1024 * 1024 // 1MB

// validateFile checks file extension and size.
func validateFile(path string) error {
	if !allowedExtensions[strings.ToLower(ext(path))] {
		return fmt.Errorf("unsupported extension: %s", ext(path))
	}
	info, err := os.Stat(path)
	if err != nil {
		return err
	}
	if info.Size() > maxFileSize {
		return fmt.Errorf("file too large: %d bytes", info.Size())
	}
	return nil
}

// ext returns the file extension including the dot.
func ext(path string) string {
	for i := len(path) - 1; i >= 0; i-- {
		if path[i] == '.' {
			return path[i:]
		}
	}
	return ""
}

// parseFlags processes command-line arguments and returns the list of files.
func parseFlags() ([]string, error) {
	fs := flag.NewFlagSet("cli", flag.ContinueOnError)
	dryRun := fs.Bool("dry-run", false, "validate without processing")
	if err := fs.Parse(os.Args[1:]); err != nil {
		return nil, err
	}
	files := fs.Args()
	if len(files) == 0 {
		return nil, fmt.Errorf("no files specified")
	}
	// Return the dry-run flag value? No, we just need to use it later.
	_ = dryRun
	return files, nil
}

func main() {
	files, err := parseFlags()
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: %v\n", err)
		os.Exit(1)
	}
	for _, f := range files {
		if err := validateFile(f); err != nil {
			fmt.Fprintf(os.Stderr, "error for %s: %v\n", f, err)
			os.Exit(1)
		}
	}
	fmt.Println("all files valid")
}

