const net = require('net');
const crypto = require('crypto');
const MAX_PACKET_SIZE = 4096;
const HEADER_SIZE = 8;
const MAGIC = 0xCAFEBABE;

function createHeader(type, payloadLen) {
  const buf = Buffer.alloc(HEADER_SIZE);
  buf.writeUInt32BE(MAGIC, 0);
  buf.writeUInt16BE(type, 4);
  buf.writeUInt16BE(payloadLen, 6);
  return buf;
}

function parseHeader(buf) {
  if (buf.length < HEADER_SIZE || buf.readUInt32BE(0) !== MAGIC) return null;
  return {
    type: buf.readUInt16BE(4),
    payloadLen: buf.readUInt16BE(6)
  };
}

function createFrame(type, payload) {
  const header = createHeader(type, payload.length);
  return Buffer.concat([header, payload]);
}

const server = net.createServer((socket) => {
  let buffer = Buffer.alloc(0);
  let state = 'WAIT_HEADER';
  let currentType = null;
  let currentPayloadLen = null;

  socket.on('data', (chunk) => {
    buffer = Buffer.concat([buffer, chunk]);

    while (true) {
      if (state === 'WAIT_HEADER') {
        if (buffer.length < HEADER_SIZE) break;
        const header = parseHeader(buffer);
        if (!header) {
          socket.destroy();
          return;
        }
        currentType = header.type;
        currentPayloadLen = header.payloadLen;
        if (currentPayloadLen > MAX_PACKET_SIZE) {
          socket.destroy();
          return;
        }
        buffer = buffer.subarray(HEADER_SIZE);
        state = 'WAIT_PAYLOAD';
      }

      if (state === 'WAIT_PAYLOAD') {
        if (buffer.length < currentPayloadLen) break;
        const payload = buffer.subarray(0, currentPayloadLen);
        buffer = buffer.subarray(currentPayloadLen);
        handleMessage(socket, currentType, payload);
        state = 'WAIT_HEADER';
      }
    }
  });

  socket.on('error', () => socket.destroy());
});

function handleMessage(socket, type, payload) {
  switch (type) {
    case 1: // PING
      socket.write(createFrame(2, Buffer.from('PONG')));
      break;
    case 3: // ECHO
      socket.write(createFrame(4, payload));
      break;
    case 5: {
      const nonce = payload.subarray(0, 16);
      const data = payload.subarray(16);
      if (data.length < 32) {
        socket.write(createFrame(6, Buffer.from('BAD_LEN')));
        break;
      }
      const hash = crypto.createHash('sha256').update(data).digest();
      const signature = payload.subarray(payload.length - 32);
      if (crypto.timingSafeEqual(hash, signature)) {
        socket.write(createFrame(6, nonce));
