_MAGIC = b'PYOBJ'
_VERSION = 3

class _CustomEncoder:
    def __init__(self, stream):
        self.stream = stream
        self._seen = set()

    def _write_byte(self, b):
        self.stream.write(bytes([b]))

    def _write_string(self, s):
        data = s.encode('utf-8')
        self._write_byte(len(data))
        self.stream.write(data)

    def encode(self, obj):
        if isinstance(obj, bool):
            self._write_byte(0x01 if obj else 0x00)
        elif isinstance(obj, int):
            self._write_byte(0x10)
            self.stream.write(struct.pack('<q', obj))
        elif isinstance(obj, float):
            self._write_byte(0x20)
            self.stream.write(struct.pack('<d', obj))
        elif isinstance(obj, str):
            self._write_byte(0x30)
            self._write_string(obj)
        elif isinstance(obj, (list, tuple)):
            self._write_byte(0x40 if isinstance(obj, list) else 0x41)
            self._write_byte(len(obj))
            for item in obj:
                self.encode(item)
        elif isinstance(obj, dict):
            self._write_byte(0x50)
            self._write_byte(len(obj))
            for k, v in obj.items():
                self.encode(k)
                self.encode(v)
        else:
            raise TypeError(f'Unsupported type: {type(obj)}')

def _decode(stream, version):
    tag = stream.read(1)[0]
    if tag == 0x00 or tag == 0x01:
        return bool(tag)
    elif tag == 0x10:
        return struct.unpack('<q', stream.read(8))[0]
    elif tag == 0x20:
        return struct.unpack('<d', stream.read(8))[0]
    elif tag == 0x30:
