        return stream.read(n).decode('utf-8')
    elif tag == 0x40 or tag == 0x41:
        n = stream.read(1)[0]
        result = [] if tag == 0x40 else tuple()
        for _ in range(n):
            item = _decode(stream, version)
            if tag == 0x40:
                result.append(item)
            else:
                result += (item,)
        return result
    elif tag == 0x50:
        n = stream.read(1)[0]
        result = {}
        for _ in range(n):
            k = _decode(stream, version)
            v = _decode(stream, version)
            result[k] = v
        return result
