const ERROR_CODES = { NETWORK: 'NETWORK_ERROR', TIMEOUT: 'TIMEOUT_ERROR', AUTH: 'AUTH_ERROR' };
class AppError extends Error { constructor(code, message) { super(message); this.code = code; } }
const API_BASE = 'https://api.example.com';
const MAX_RETRIES = 3;
const TIMEOUT_MS = 5000;

async function fetchWithTimeout(url, options = {}) {
  const controller = new AbortController();
  const timeoutId = setTimeout(() => controller.abort(), TIMEOUT_MS);
  try {
    const response = await fetch(url, { ...options, signal: controller.signal });
    clearTimeout(timeoutId);
    if (!response.ok) {
      throw new AppError(ERROR_CODES.NETWORK, `HTTP ${response.status}`);
    }
    return await response.json();
  } catch (err) {
    clearTimeout(timeoutId);
    if (err.name === 'AbortError') {
      throw new AppError(ERROR_CODES.TIMEOUT, 'Request timed out');
    }
    throw err;
  }
}

function isRetryable(err) {
  return err.code === ERROR_CODES.NETWORK || err.code === ERROR_CODES.TIMEOUT;
}

async function getUserData(userId) {
  return fetchWithTimeout(`${API_BASE}/users/${userId}`);
}

async function getUserPosts(userId) {
  return fetchWithTimeout(`${API_BASE}/users/${userId}/posts`);
}

async function handleUserRequest(userId) {
  let attempts = 0;
  while (attempts < MAX_RETRIES) {
    try {
      const [user, posts] = await Promise.all([getUserData(userId), getUserPosts(userId)]);
      return { user, posts };
    } catch (err) {
      attempts++;
      if (!isRetryable(err) || attempts >= MAX_RETRIES) throw err;
      await new Promise(resolve => setTimeout(resolve, 1000 * attempts));
    }
  }
  throw new AppError(ERROR_CODES.NETWORK, 'Max retries exceeded');
}

async function main() {
  try {
    const result = await handleUserRequest(42);
    console.log('Success:', result.user.name);
  } catch (err) {
    if (err instanceof AppError) {
      console.error(`Error [${err.code}]: ${err.message}`);
      if (err.code === ERROR_CODES.AUTH) {
        console.error('Redirect to login');
      }
    } else {
      console.error('Unexpected error:', err);
    }
  }
}

