const TYPE_TAG = '__type__';
const registry = new Map();

function registerType(name, serialize, deserialize) {
  registry.set(name, { serialize, deserialize });
}

function serialize(value, seen = new Map()) {
  if (value === null || typeof value !== 'object') {
    return value;
  }
  if (seen.has(value)) {
    return { [TYPE_TAG]: 'ref', id: seen.get(value) };
  }
  const id = seen.size;
  seen.set(value, id);

  const type = value.constructor && value.constructor.name;
  const entry = registry.get(type);
  if (entry) {
    return {
      [TYPE_TAG]: type,
      id,
      data: entry.serialize(value, (inner) => serialize(inner, seen))
    };
  }

  if (Array.isArray(value)) {
    return {
      [TYPE_TAG]: 'array',
      id,
      items: value.map((item) => serialize(item, seen))
    };
  }

  const obj = {};
  for (const key of Object.keys(value)) {
    obj[key] = serialize(value[key], seen);
  }
  return { [TYPE_TAG]: 'object', id, data: obj };
}

function deserialize(data, refs = new Map()) {
  if (data === null || typeof data !== 'object') {
    return data;
  }
  if (data[TYPE_TAG] === 'ref') {
    return refs.get(data.id);
  }
  const { id, data: inner } = data;
  const entry = registry.get(data[TYPE_TAG]);
  if (entry) {
    const obj = entry.deserialize(inner, (sub) => deserialize(sub, refs));
    refs.set(id, obj);
    return obj;
  }
  if (data[TYPE_TAG] === 'array') {
    const arr = [];
    refs.set(id, arr);
    inner.items.forEach((item) => arr.push(deserialize(item, refs)));
    return arr;
  }
  const obj = {};
  refs.set(id, obj);
  for (const key of Object.keys(inner)) {
