function bestRationalApprox(target, maxDen) {
  // Returns [numerator, denominator] of the best rational approximation
  // with denominator <= maxDen, using continued fractions.
  const cf = [];
  let a = Math.floor(target);
  let num = target - a;
  cf.push(a);
  while (Math.abs(num) > 1e-12 && cf.length < 20) {
    num = 1 / num;
    a = Math.floor(num);
    cf.push(a);
    num = num - a;
  }

  // Build convergents and track the best approximation
  let best = [Math.round(target), 1];
  let bestErr = Math.abs(target - best[0]);

  // Walk through the continued fraction terms
  let hPrev = 0, hCurr = 1;
  let kPrev = 1, kCurr = 0;

  for (let i = 0; i < cf.length; i++) {
    const a = cf[i];
    const hNext = a * hCurr + hPrev;
    const kNext = a * kCurr + kPrev;
    hPrev = hCurr;
    hCurr = hNext;
    kPrev = kCurr;
    kCurr = kNext;

    if (kCurr > maxDen) break;

    // Check the current convergent
    const err = Math.abs(target - hCurr / kCurr);
    if (err < bestErr - 1e-15) {
      best = [hCurr, kCurr];
      bestErr = err;
    }

    // If the next convergent (with next term) would exceed maxDen,
    // consider the semiconvergents (using the previous convergent).
    if (i + 1 < cf.length) {
      const nextA = cf[i + 1];
      for (let t = 1; t < nextA; t++) {
        const hSem = t * hCurr + hPrev;
        const kSem = t * kCurr + kPrev;
        if (kSem > maxDen) break;
        const errSem = Math.abs(target - hSem / kSem);
        if (errSem < bestErr - 1e-15) {
          best = [hSem, kSem];
          bestErr = errSem;
        }
      }
    }
  }

  return best;
}

