  const regex = /{{\s*([a-zA-Z_][a-zA-Z0-9_]*)\s*}}/g;
  const vars = [];
  let match;
  while ((match = regex.exec(template)) !== null) {
    if (!vars.includes(match[1])) {
      vars.push(match[1]);
    }
  }
  return vars;
}

function validateTemplate(template, context) {
  const vars = extractVars(template);
  for (const v of vars) {
    if (!(v in context)) {
