const MAGIC = 0x5A;
const VERSION = 1;

class PacketEncoder {
  constructor() {
    this.buffer = new Uint8Array(1024);
    this.offset = 0;
  }

  writeByte(value) {
    this.buffer[this.offset++] = value & 0xFF;
  }

  writeShort(value) {
    this.writeByte((value >> 8) & 0xFF);
    this.writeByte(value & 0xFF);
  }

  writeInt(value) {
    this.writeShort((value >> 16) & 0xFFFF);
    this.writeShort(value & 0xFFFF);
  }

  writeString(str) {
    const bytes = new TextEncoder().encode(str);
    this.writeShort(bytes.length);
    for (const b of bytes) this.writeByte(b);
  }

  getData() {
    return this.buffer.slice(0, this.offset);
  }
}

class PacketDecoder {
  constructor(data) {
    this.data = data;
    this.offset = 0;
  }

  readByte() {
    if (this.offset >= this.data.length) throw new Error('Buffer underrun');
    return this.data[this.offset++];
  }

  readShort() {
    const high = this.readByte();
    const low = this.readByte();
    return (high << 8) | low;
  }

  readInt() {
    const high = this.readShort();
    const low = this.readShort();
    return (high << 16) | low;
  }

  readString() {
    const len = this.readShort();
    if (this.offset + len > this.data.length) throw new Error('String overflow');
    const bytes = this.data.slice(this.offset, this.offset + len);
    this.offset += len;
    return new TextDecoder().decode(bytes);
  }

  hasMore() {
    return this.offset < this.data.length;
  }
}

function serializePacket(packet) {
  const enc = new PacketEncoder();
  enc.writeByte(MAGIC);
  enc.writeByte(VERSION);
  enc.writeByte(packet.type);
  enc.writeInt(packet.id);
  enc.writeString(packet.payload);
  return enc.getData();
}

function deserializePacket(data) {
  const dec = new PacketDecoder(data);
  if (dec.readByte() !== MAGIC) throw new Error('Bad magic');
  if (dec.readByte() !== VERSION) throw new Error('Bad version');
  const type = dec.readByte();
  const id = dec.readInt();
  const payload = dec.readString();
  if (dec.hasMore()) throw new Error('Trailing bytes');
  return { type, id, payload };
}

