import struct
import socket

# TCP segment header layout: source_port(2), dest_port(2), seq(4), ack(4), flags(2), window(2), checksum(2), urgent(2)
HEADER_FORMAT = '!HHIIHHHH'
HEADER_SIZE = struct.calcsize(HEADER_FORMAT)

class TcpStreamAssembler:
    def __init__(self, initial_seq):
        self.buffer = bytearray()
        self.next_expected = initial_seq
        self.fragments = {}

    def add_segment(self, seq, payload):
        """Add a segment, handling out-of-order and overlapping data."""
        if seq < self.next_expected:
            overlap = self.next_expected - seq
            if overlap >= len(payload):
                return
            payload = payload[overlap:]
            seq = self.next_expected

        if seq > self.next_expected:
            self.fragments[seq] = payload
            return

        self.buffer.extend(payload)
        self.next_expected = seq + len(payload)
        self._flush_contiguous()

    def _flush_contiguous(self):
        while True:
            seq = self.next_expected
            if seq in self.fragments:
                payload = self.fragments.pop(seq)
                self.buffer.extend(payload)
                self.next_expected = seq + len(payload)
            else:
                break

    def get_data(self):
        return bytes(self.buffer)

def parse_tcp_segment(raw):
    if len(raw) < HEADER_SIZE:
        return None
    src_port, dst_port, seq, ack, flags, window, checksum, urgent = struct.unpack(HEADER_FORMAT, raw[:HEADER_SIZE])
    data_offset = (flags >> 12) & 0xF
    header_len = data_offset * 4
    if header_len < HEADER_SIZE:
        return None
    payload = raw[header_len:]
    return {'seq': seq, 'payload': payload}

