// Packed data structure: 2-byte magic, 2-byte version, 4-byte length, then payload.
// Payload is a sequence of records: each record has 1-byte type, 2-byte size, then size bytes.

static uint16_t be16(uint16_t v) { return __builtin_bswap16(v); }
static uint32_t be32(uint32_t v) { return __builtin_bswap32(v); }

int serialize_record(uint8_t *buf, size_t buf_len, uint8_t type, const uint8_t *data, size_t len) {
    if (buf_len < 3 + len) return -1;
    buf[0] = type;
    uint16_t sz = be16((uint16_t)len);
    memcpy(buf+1, &sz, 2);
    memcpy(buf+3, data, len);
    return (int)(3+len);
}

int deserialize_record(const uint8_t *buf, size_t buf_len, uint8_t *type_out, const uint8_t **data_out, size_t *len_out) {
    if (buf_len < 3) return -1;
    *type_out = buf[0];
    uint16_t sz;
    memcpy(&sz, buf+1, 2);
    sz = be16(sz);
    if (buf_len < 3 + sz) return -1;
    *len_out = sz;
    *data_out = buf+3;
    return (int)(3+sz);
