let lastResult = null;

function flakyOperation() {
  attemptCount++;
  if (attemptCount < 3) {
    throw new RetryableError('temporary failure', attemptCount);
  }
  return 'success';
}

function executeWithRetry(operation, maxRetries) {
  let lastError;
  for (let attempt = 1; attempt <= maxRetries; attempt++) {
    try {
      return operation();
    } catch (err) {
      if (err instanceof RetryableError && attempt < maxRetries) {
        lastError = err;
        continue;
      }
      throw err;
    }
  }
  throw lastError;
}

