static int is_within_root(const char *root, const char *path) {
    size_t rlen = strlen(root);
    size_t plen = strlen(path);
    if (plen < rlen) return 0;
    if (strncmp(root, path, rlen) != 0) return 0;
    if (path[rlen] != '/' && path[rlen] != '\0') return 0;
    return 1;
}

static void normalize_path(const char *input, char *output, size_t out_size) {
    char temp[MAX_PATH];
    snprintf(temp, sizeof(temp), "%s", input);
    char *parts[MAX_PATH/2];
    int nparts = 0;
    char *tok = strtok(temp, "/");
    while (tok) {
        if (strcmp(tok, ".") == 0) {
            // skip
        } else if (strcmp(tok, "..") == 0) {
            if (nparts > 0) nparts--;
        } else {
            parts[nparts++] = tok;
        }
        tok = strtok(NULL, "/");
    }
    output[0] = '\0';
    for (int i = 0; i < nparts; i++) {
        strncat(output, "/", out_size - strlen(output) - 1);
        strncat(output, parts[i], out_size - strlen(output) - 1);
    }
    if (nparts == 0) strncat(output, "/", out_size - strlen(output) - 1);
}

static int is_symlink(const char *path) {
    struct stat st;
    if (lstat(path, &st) != 0) return 0;
    return S_ISLNK(st.st_mode);
}

static int safe_open(const char *root, const char *user_path) {
    char resolved_root[PATH_MAX];
    char resolved_path[PATH_MAX];
    char normalized[PATH_MAX];

    if (realpath(root, resolved_root) == NULL) return -1;

    // Resolve symlinks in user_path after normalization
    normalize_path(user_path, normalized, sizeof(normalized));
    char full_path[PATH_MAX];
    snprintf(full_path, sizeof(full_path), "%s%s", resolved_root, normalized);

    if (realpath(full_path, resolved_path) == NULL) return -1;

    if (!is_within_root(resolved_root, resolved_path)) return -1;

    return open(resolved_path, O_RDONLY);
}

