func (t *Temperature) UnmarshalJSON(data []byte) error {
    var raw string
    if err := json.Unmarshal(data, &raw); err != nil {
        return err
    }
    var val float64
    var unit string
    if _, err := fmt.Sscanf(raw, "%f %s", &val, &unit); err != nil {
        return err
    }
    switch unit {
    case "C":
        *t = Temperature(val)
    case "F":
        *t = Temperature((val - 32) * 5 / 9)
    default:
        return fmt.Errorf("unknown unit %q", unit)
    }
    return nil
}

