const input = '3 + 4 * (2 - 1) + 6 / 2';
let pos = 0;
function nextToken() {
  while (pos < input.length && input[pos] === ' ') pos++;
  if (pos >= input.length) return null;
  const ch = input[pos];
  if (/\d/.test(ch)) {
    let num = '';
    while (pos < input.length && /\d/.test(input[pos])) num += input[pos++];
    return { type: 'NUM', value: Number(num) };
  }
  if ('+-*/()'.includes(ch)) return { type: ch, value: ch };
  throw new Error('Unexpected char: ' + ch);
}
let current = nextToken();
function consume(expected) {
  if (current && current.type === expected) current = nextToken();
  else throw new Error('Expected ' + expected);
}
function parseExpression() {
  let left = parseTerm();
  while (current && (current.type === '+' || current.type === '-')) {
    const op = current.type;
    consume(op);
    left = { type: 'BinOp', op, left, right: parseTerm() };
  }
  return left;
}
function parseTerm() {
  let left = parseFactor();
  while (current && (current.type === '*' || current.type === '/')) {
    const op = current.type;
    consume(op);
    left = { type: 'BinOp', op, left, right: parseFactor() };
  }
  return left;
}
function parseFactor() {
  if (current.type === 'NUM') {
    const num = { type: 'Num', value: current.value };
    consume('NUM');
    return num;
  }
  if (current.type === '(') {
    consume('(');
    const expr = parseExpression();
    consume(')');
    return expr;
  }
  throw new Error('Unexpected token: ' + current.type);
}
function evaluate(node) {
  if (node.type === 'Num') return node.value;
  const leftVal = evaluate(node.left);
  const rightVal = evaluate(node.right);
  switch (node.op) {
    case '+': return leftVal + rightVal;
    case '-': return leftVal - rightVal;
    case '*': return leftVal * rightVal;
    case '/': return leftVal / rightVal;
  }
}

