// mat is a square matrix represented as a flat slice, row-major.
type mat []float64

// size returns the dimension n of an n x n matrix.
func (m mat) size() int {
	s := 0
	for 1<<uint(s) < len(m) {
		s++
	}
	return s
}

// determinant computes the determinant of m using cofactor expansion.
// It assumes m is a valid square matrix with size at least 1.
func (m mat) determinant() float64 {
	n := m.size()
	if n == 1 {
		return m[0]
	}
	if n == 2 {
		return m[0]*m[3] - m[1]*m[2]
	}
	det := 0.0
	sign := 1.0
	for col := 0; col < n; col++ {
		// Build submatrix by removing row 0 and column col.
		sub := make(mat, 0, (n-1)*(n-1))
		for r := 1; r < n; r++ {
			for c := 0; c < n; c++ {
				if c == col {
					continue
				}
				sub = append(sub, m[r*n+c])
			}
		}
		det += sign * m[col] * sub.determinant()
		sign = -sign
	}
	return det
}

// identity returns an n x n identity matrix.
func identity(n int) mat {
	m := make(mat, n*n)
	for i := 0; i < n; i++ {
		m[i*n+i] = 1
	}
	return m
}

// multiply returns the product a*b for square matrices of same size.
func multiply(a, b mat) mat {
	n := a.size()
	res := make(mat, n*n)
	for i := 0; i < n; i++ {
		for j := 0; j < n; j++ {
			sum := 0.0
			for k := 0; k < n; k++ {
				sum += a[i*n+k] * b[k*n+j]
			}
			res[i*n+j] = sum
		}
	}
	return res
}

// cofactorMatrix computes the cofactor matrix of m.
// It is defined as C[i][j] = (-1)^(i+j) * det(minor(i,j)).
// The minor is m with row i and column j removed.
func cofactorMatrix(m mat) mat {
	n := m.size()
	c := make(mat, n*n)
	for i := 0; i < n; i++ {
		for j := 0; j < n; j++ {
			minor := make(mat, 0, (n-1)*(n-1))
			for r := 0; r < n; r++ {
				if r == i {
					continue
