func process(ctx context.Context, in <-chan int, out chan<- result) {
	for {
		select {
		case <-ctx.Done():
			return
		case v, ok := <-in:
			if !ok {
				return
			}
			// simulate work
			time.Sleep(10 * time.Millisecond)
			out <- result{value: v * 2}
