	output := make(chan result, 10)

	var wg sync.WaitGroup
	const numWorkers = 3

	for i := 0; i < numWorkers; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			process(ctx, input, output)
		}()
	}

	// Feed input
	go func() {
		defer close(input)
		for i := 0; i < 100; i++ {
			select {
			case <-ctx.Done():
				return
			case input <- i:
			}
		}
	}()

	// Close output when all workers are done
	go func() {
		wg.Wait()
		close(output)
	}()

	// Collect results until output is closed
	var count int
	for r := range output {
		if r.err != nil {
			fmt.Println("error:", r.err)
			continue
		}
		count++
	}
