const crypto = require('crypto');
const net = require('net');

const HEADER_LEN = 24;
const MAGIC = 0x534f434b;
const OP_HELLO = 1;
const OP_DATA = 2;

function makeHeader(opcode, length) {
  const buf = Buffer.alloc(HEADER_LEN);
  buf.writeUInt32BE(MAGIC, 0);
  buf.writeUInt8(opcode, 4);
  buf.writeUInt16BE(length, 5);
  buf.fill(0, 7, 24);
  return buf;
}

function parseHeader(buf) {
  if (buf.length !== HEADER_LEN) throw new Error('bad header');
  const magic = buf.readUInt32BE(0);
  if (magic !== MAGIC) throw new Error('bad magic');
  const op = buf.readUInt8(4);
  const len = buf.readUInt16BE(5);
  return { op, len };
}

function encryptPayload(data, key) {
  const iv = crypto.randomBytes(16);
  const cipher = crypto.createCipheriv('aes-256-cbc', key, iv);
  const encrypted = Buffer.concat([cipher.update(data), cipher.final()]);
  return Buffer.concat([iv, encrypted]);
}

