package main

import (
	"bytes"
	"encoding/binary"
	"fmt"
	"io"
)

type Person struct {
	Name string
	Age  int32
}

const magic = 0x50455253 // 'PERS'

func encodePerson(p Person) ([]byte, error) {
	buf := new(bytes.Buffer)
	if err := binary.Write(buf, binary.LittleEndian, magic); err != nil {
		return nil, err
	}
	if err := binary.Write(buf, binary.LittleEndian, int32(len(p.Name))); err != nil {
		return nil, err
	}
	if err := binary.Write(buf, binary.LittleEndian, []byte(p.Name)); err != nil {
		return nil, err
	}
	if err := binary.Write(buf, binary.LittleEndian, p.Age); err != nil {
		return nil, err
	}
	return buf.Bytes(), nil
}

func decodePerson(data []byte) (Person, error) {
	r := bytes.NewReader(data)
	var m int32
	if err := binary.Read(r, binary.LittleEndian, &m); err != nil {
		return Person{}, err
	}
	if m != magic {
		return Person{}, fmt.Errorf("invalid magic: %x", m)
	}
	var nameLen int32
	if err := binary.Read(r, binary.LittleEndian, &nameLen); err != nil {
		return Person{}, err
	}
	nameBytes := make([]byte, nameLen)
	if err := binary.Read(r, binary.LittleEndian, nameBytes); err != nil {
		return Person{}, err
	}
	var age int32
	if err := binary.Read(r, binary.LittleEndian, &age); err != nil {
		return Person{}, err
	}
	return Person{Name: string(nameBytes), Age: age}, nil
}

func main() {
	p := Person{Name: "Alice", Age: 30}
	encoded, err := encodePerson(p)
	if err != nil {
		panic(err)
	}
	decoded, err := decodePerson(encoded)
	if err != nil {
		panic(err)
	}
	fmt.Printf("%+v\n", decoded)
}

package main

import (
	"fmt"
	"net"
	"strconv"
	"strings"
	"sync"
)

const (
	MAX_PAYLOAD = 1024
	HEADER_LEN  = 8
)

// Message types
const (
	TYPE_DATA = 1
	TYPE_ACK  = 2
)

func encodeHeader(msgType byte, payloadLen int) []byte {
	hdr := make([]byte, HEADER_LEN)
	hdr[0] = msgType
	hdr[1] = 0
	hdr[2] = 0
	hdr[3] = 0
	hdr[4] = byte(payloadLen >> 24)
	hdr[5] = byte(payloadLen >> 16)
	hdr[6] = byte(payloadLen >> 8)
	hdr[7] = byte(payloadLen)
	return hdr
}

func decodeHeader(hdr []byte) (byte, int) {
	msgType := hdr[0]
	payloadLen := (int(hdr[4]) << 24) | (int(hdr[5]) << 16) | (int(hdr[6]) << 8) | int(hdr[7])
	return msgType, payloadLen
}

func handleConnection(conn net.Conn) {
	defer conn.Close()
	var buffer []byte
	var expectedLen int = 0
	var state int = 0 // 0: waiting header, 1: waiting payload
	for {
		if state == 0 {
			if len(buffer) < HEADER_LEN {
				chunk := make([]byte, 512)
				n, err := conn.Read(chunk)
				if err != nil || n == 0 { return }
				buffer = concat(buffer, chunk[0:n])
				continue
			}
			msgType, payloadLen := decodeHeader(buffer[0:HEADER_LEN])
			buffer = buffer[HEADER_LEN:]
			if payloadLen > MAX_PAYLOAD { return }
			expectedLen = payloadLen
			state = 1
			if payloadLen == 0 {
				// zero-length payload, process immediately
				processMessage(msgType, []byte)
				state = 0
			}
		} else {
			if len(buffer) < expectedLen {
				chunk := make([]byte, 512)
				n, err := conn.Read(chunk)
				if err != nil || n == 0 { return }
				buffer = concat(buffer, chunk[0:n])
				continue
			}
			payload := buffer[0:expectedLen]
			buffer = buffer[expectedLen:]
			processMessage(msgType, payload)
			state = 0
		}
	}
}

func processMessage(msgType byte, payload []byte) {
	// handle based on type
	if msgType == TYPE_DATA {
		// echo back with ACK
		ackPayload := make([]byte, 4)
		ackPayload[0] = byte(len(payload) >> 24)
		ackPayload[1] = byte(len(payload) >> 16)
		ackPayload[2] = byte(len(payload) >> 8)
		ackPayload[3] = byte(len(payload))
		sendMessage(TYPE_ACK, ackPayload)
	} else if msgType == TYPE_ACK {
		fmt.Println("Received ACK")
	} else {
		fmt.Println("Unknown message type")
	}
}

var conn net.Conn

func sendMessage(msgType byte, payload []byte) {
	hdr := encodeHeader(msgType, len(payload))
	conn.Write(hdr)
	if len(payload) > 0 { conn.Write(payload) }
}

func main() {
	ln, err := net.Listen("tcp", ":8080")
	if err != nil { panic(err) }
	for {
		c, err := ln.Accept()
		if err != nil { continue }
		go handleConnection(c)
	}
}

