package main

import (
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

const maxDepth = 5

type dirInfo struct {
	path string
	size int64
}

var visited = make(map[string]bool)

func resolveSymlink(path string) (string, error) {
	for i := 0; i < maxDepth; i++ {
		info, err := os.Lstat(path)
		if err != nil {
			return "", err
		}
		if info.Mode()&os.ModeSymlink == 0 {
			return path, nil
		}
		link, err := os.Readlink(path)
		if err != nil {
			return "", err
		}
		if !filepath.IsAbs(link) {
			link = filepath.Join(filepath.Dir(path), link)
		}
		path = link
	}
	return "", errors.New("too many symlink levels")
}

func walkDir(path string, depth int) ([]dirInfo, error) {
	if depth > maxDepth {
		return nil, errors.New("max depth exceeded")
	}
	resolved, err := resolveSymlink(path)
	if err != nil {
		return nil, err
	}
	if visited[resolved] {
		return nil, nil
	}
	visited[resolved] = true

	entries, err := os.ReadDir(resolved)
	if err != nil {
		return nil, err
	}

	var dirs []dirInfo
	for _, entry := range entries {
		full := filepath.Join(resolved, entry.Name())
		info, err := entry.Info()
		if err != nil {
			continue
		}
		if info.IsDir() {
			subDirs, err := walkDir(full, depth+1)
			if err != nil {
				return nil, err
			}
			dirs = append(dirs, subDirs...)
			dirs = append(dirs, dirInfo{path: full, size: info.Size()})
		}
	}
	return dirs, nil
}

func main() {
	root := "/tmp/testroot"
	dirs, err := walkDir(root, 0)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: %v\n", err)
		os.Exit(1)
	}

	var total int64
	var names []string
	for _, d := range dirs {
		total += d.size
		names = append(names, d.path)
	}

	fmt.Printf("visited %d dirs, total size %d\n", len(names), total)
	fmt.Println(strings.Join(names, "\n"))
}

