static int copy_file(const char *src, const char *dst) {
    int in_fd = open(src, O_RDONLY);
    if (in_fd < 0) return -1;
    int out_fd = open(dst, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (out_fd < 0) { close(in_fd); return -1; }
    char buf[BUF_SIZE];
    ssize_t n;
    while ((n = read(in_fd, buf, sizeof(buf))) > 0) {
        if (write(out_fd, buf, n) != n) {
            close(in_fd); close(out_fd); return -1;
        }
    }
    close(in_fd); close(out_fd);
    return (n == 0) ? 0 : -1;
}

static int copy_directory_contents(const char *src_dir, const char *dst_dir) {
    DIR *dir = opendir(src_dir);
    if (!dir) return -1;
    if (mkdir(dst_dir, 0755) != 0 && errno != EEXIST) {
        closedir(dir);
        return -1;
    }
    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0)
            continue;
        char src_path[PATH_MAX], dst_path[PATH_MAX];
        snprintf(src_path, sizeof(src_path), "%s/%s", src_dir, entry->d_name);
        snprintf(dst_path, sizeof(dst_path), "%s/%s", dst_dir, entry->d_name);
        if (entry->d_type == DT_REG) {
            if (copy_file(src_path, dst_path) != 0) {
                closedir(dir);
                return -1;
            }
        } else if (entry->d_type == DT_DIR) {
            if (copy_directory_contents(src_path, dst_path) != 0) {
                closedir(dir);
                return -1;
            }
        }
    }
    closedir(dir);
    return 0;
}

