#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct Entry {
    char* key;
    int value;
    struct Entry* next;
} Entry;

typedef struct {
    Entry** buckets;
    int size;
} HashMap;

unsigned int hash(const char* key, int size) {
    unsigned int h = 0;
    while (*key) h = (h << 5) + *key++;
    return h % size;
}

HashMap* create_map(int size) {
    HashMap* map = malloc(sizeof(HashMap));
    map->size = size;
    map->buckets = calloc(size, sizeof(Entry*));
    return map;
}

void free_map(HashMap* map) {
    for (int i = 0; i < map->size; i++) {
        Entry* e = map->buckets[i];
        while (e) {
            Entry* next = e->next;
            free(e->key);
            free(e);
            e = next;
        }
    }
    free(map->buckets);
    free(map);
}

void put(HashMap* map, const char* key, int value) {
    unsigned int idx = hash(key, map->size);
    Entry* e = map->buckets[idx];
    while (e) {
        if (strcmp(e->key, key) == 0) {
            e->value = value;
            return;
        }
        e = e->next;
    }
    Entry* new = malloc(sizeof(Entry));
    new->key = strdup(key);
    new->value = value;
    new->next = map->buckets[idx];
    map->buckets[idx] = new;
}

int* get(HashMap* map, const char* key) {
    unsigned int idx = hash(key, map->size);
    Entry* e = map->buckets[idx];
    while (e) {
        if (strcmp(e->key, key) == 0) return &e->value;
        e = e->next;
    }
    return NULL;
}

int main() {
    HashMap* map = create_map(16);
    put(map, "one", 1);
    put(map, "two", 2);
    put(map, "three", 3);

    int* val = get(map, "two");
    if (val) printf("%d\n", *val);

    free_map(map);
    return 0;
}

