#define OPT_VERBOSE 0x1
#define OPT_RECURSIVE 0x2
#define OPT_FORCE 0x4

static const struct option long_opts[] = {
    {"verbose", no_argument, 0, 'v'},
    {"recursive", no_argument, 0, 'r'},
    {"force", no_argument, 0, 'f'},
    {0, 0, 0, 0}
};

