static void print_usage(const char *prog) {
    fprintf(stderr, "Usage: %s [-vrf] [file...]\n", prog);
}

static void process_flags(void) {
    if (flags & OPT_VERBOSE) printf("Verbose mode on\n");
    if (flags & OPT_RECURSIVE) printf("Recursive mode on\n");
    if (flags & OPT_FORCE) printf("Force mode on\n");
}

int main(int argc, char **argv) {
    int opt;
    int opt_index = 0;

    while ((opt = getopt_long(argc, argv, "vrf", long_opts, &opt_index)) != -1) {
        switch (opt) {
        case 'v':
            flags |= OPT_VERBOSE;
            break;
        case 'r':
            flags |= OPT_RECURSIVE;
            break;
        case 'f':
            flags |= OPT_FORCE;
            break;
        default:
            print_usage(argv[0]);
            return EXIT_FAILURE;
        }
    }

    if (optind >= argc) {
        print_usage(argv[0]);
        return EXIT_FAILURE;
    }

    process_flags();

    for (int i = optind; i < argc; i++) {
        printf("Processing %s\n", argv[i]);
    }

    return EXIT_SUCCESS;
}

