void print_error(const char *msg) {
    fprintf(stderr, "Error: %s\n", msg);
}

int count_files(const char *path) {
    DIR *dir = opendir(path);
    if (!dir) {
        print_error("cannot open dir");
        return -1;
    }
    int count = 0;
    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0)
            continue;
        char full_path[1024];
        snprintf(full_path, sizeof(full_path), "%s/%s", path, entry->d_name);
        struct stat st;
        if (lstat(full_path, &st) == -1) {
            print_error("stat failed");
            continue;
        }
        if (S_ISDIR(st.st_mode)) {
            count += count_files(full_path);
        } else {
            count++;
        }
    }
    closedir(dir);
    return count;
}

int count_special(const char *path) {
    DIR *dir = opendir(path);
    if (!dir) {
        print_error("cannot open dir");
        return -1;
    }
    int count = 0;
    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0)
            continue;
        char full_path[1024];
        snprintf(full_path, sizeof(full_path), "%s/%s", path, entry->d_name);
        struct stat st;
        if (lstat(full_path, &st) == -1) {
            print_error("stat failed");
            continue;
        }
        if (S_ISDIR(st.st_mode)) {
            count += count_special(full_path);
        } else {
            if (st.st_nlink > 1) {
                count++;
            }
        }
    }
    closedir(dir);
    return count;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <directory>\n", argv[0]);
        return 1;
    }
    int total = count_files(argv[1]);
    int special = count_special(argv[1]);
    printf("Total files: %d\n", total);
    printf("Files with hard links: %d\n", special);
    printf("Regular files only: %d\n", total - special);
    return 0;
}

package main

import "fmt"

type TreeNode struct {
    Val   int
    Left  *TreeNode
    Right *TreeNode
}

// buildTree constructs a fixed binary tree for demonstration.
func buildTree() *TreeNode {
    //      5
    //     / \
    //    3   8
    //   / \   \
    //  1   4   10
    return &TreeNode{
        Val: 5,
        Left: &TreeNode{
            Val: 3,
            Left:  &TreeNode{Val: 1},
            Right: &TreeNode{Val: 4},
        },
        Right: &TreeNode{
            Val: 8,
            Right: &TreeNode{Val: 10},
        },
    }
}

// flattenToSortedSlice performs an inorder traversal and appends to *[]int.
func flattenToSortedSlice(root *TreeNode, out *[]int) {
    if root == nil {
        return
    }
    flattenToSortedSlice(root.Left, out)
    *out = append(*out, root.Val)
    flattenToSortedSlice(root.Right, out)
}

// buildBalancedFromSlice constructs a balanced BST from a sorted slice.
// The slice is assumed to be sorted in ascending order.
func buildBalancedFromSlice(nums []int) *TreeNode {
    if len(nums) == 0 {
        return nil
    }
    mid := len(nums) / 2
    return &TreeNode{
        Val:   nums[mid],
        Left:  buildBalancedFromSlice(nums[:mid]),
        Right: buildBalancedFromSlice(nums[mid+1:]),
    }
}

// balanceTree takes a BST and returns a balanced BST with the same elements.
func balanceTree(root *TreeNode) *TreeNode {
    // In-order traversal to get sorted elements
    var sorted []int
    flattenToSortedSlice(root, &sorted)
    // Rebuild balanced from sorted slice
    return buildBalancedFromSlice(sorted)
}

func printInorder(root *TreeNode) {
    if root == nil {
        return
    }
    printInorder(root.Left)
    fmt.Printf("%d ", root.Val)
    printInorder(root.Right)
}

func main() {
    original := buildTree()
    fmt.Println("Original inorder:")
    printInorder(original)
    fmt.Println()

    balanced := balanceTree(original)

    fmt.Println("Balanced inorder:")
    printInorder(balanced)
    fmt.Println()

    // Check balance property: height difference between left and right subtrees
    // of the balanced tree should be at most 1.
    if isBalanced(balanced) {
        fmt.Println("The tree is balanced.")
    } else {
        fmt.Println("The tree is not balanced.")
    }
}

// isBalanced checks if the tree is height-balanced.
func isBalanced(root *TreeNode) bool {
    if root == nil {
        return true
    }
    leftH := height(root.Left)
    rightH := height(root.Right)
    if abs(leftH-rightH) > 1 {
        return false
    }
    return isBalanced(root.Left) && isBalanced(root.Right)
}

// height returns the height of the tree.
func height(root *TreeNode) int {
    if root == nil {
        return 0
    }
    lh := height(root.Left)
    rh := height(root.Right)
    if lh > rh {
        return lh + 1
    }
    return rh + 1
}

// abs returns the absolute value of an integer.
func abs(x int) int {
    if x < 0 {
        return -x
    }
    return x
}

