#include <poll.h>
#include <stddef.h>
#include <stdint.h>

#define MAX_FDS 16
#define POLL_TIMEOUT_MS 500

struct conn {
    int fd;
    uint32_t last_activity;
};

static struct conn conns[MAX_FDS];
static int conn_count = 0;

static int add_conn(int fd) {
    if (conn_count >= MAX_FDS) return -1;
    conns[conn_count].fd = fd;
    conns[conn_count].last_activity = 0;
    return conn_count++;
}

static int remove_conn(int idx) {
    if (idx < 0 || idx >= conn_count) return -1;
    conns[idx] = conns[--conn_count];
    return 0;
}

static int get_conn_idx(int fd) {
    for (int i = 0; i < conn_count; i++) {
        if (conns[i].fd == fd) return i;
    }
    return -1;
}

static void process_events(struct pollfd *fds, int nfds, uint32_t now) {
    for (int i = 0; i < nfds; i++) {
        int idx = get_conn_idx(fds[i].fd);
        if (idx < 0) continue;
        if (fds[i].revents & (POLLIN | POLLOUT)) {
            conns[idx].last_activity = now;
        }
        if (fds[i].revents & (POLLERR | POLLHUP | POLLNVAL)) {
            remove_conn(idx);
        }
    }
}

static int check_timeouts(uint32_t now, uint32_t timeout_ms) {
    int removed = 0;
    for (int i = 0; i < conn_count; ) {
        if (now - conns[i].last_activity > timeout_ms) {
            remove_conn(i);
            removed++;
        } else {
            i++;
        }
    }
    return removed;
}

