// Tokenize a string into words, storing each word in out[] (max n words).
// Returns the number of words found.
int tokenize(const char *s, char out[][MAX_WORD_LEN], int n) {
    int count = 0;
    const char *p = s;
    while (*p && count < n) {
        while (*p && isspace((unsigned char)*p)) p++;
        if (!*p) break;
        int len = 0;
        while (*p && !isspace((unsigned char)*p) && len < MAX_WORD_LEN-1) {
            out[count][len++] = *p++;
        }
        out[count][len] = '\0';
        count++;
    }
    return count;
}

