package main

import (
	"encoding/binary"
	"fmt"
	"net"
)

// packetHeader represents a minimal IPv4 header.
type packetHeader struct {
	versionIHL  byte
	tos         byte
	totalLength uint16
	id          uint16
	flagsFrag   uint16
	ttl         byte
	protocol    byte
	checksum    uint16
	srcIP       [4]byte
	dstIP       [4]byte
}

// parseHeader extracts header fields from raw bytes.
func parseHeader(b []byte) packetHeader {
	var h packetHeader
	h.versionIHL = b[0]
	h.tos = b[1]
	h.totalLength = binary.BigEndian.Uint16(b[2:4])
	h.id = binary.BigEndian.Uint16(b[4:6])
	h.flagsFrag = binary.BigEndian.Uint16(b[6:8])
	h.ttl = b[8]
	h.protocol = b[9]
	h.checksum = binary.BigEndian.Uint16(b[10:12])
	copy(h.srcIP[:], b[12:16])
	copy(h.dstIP[:], b[16:20])
	return h
}

// computeChecksum calculates the IPv4 header checksum over the first 20 bytes.
func computeChecksum(b []byte) uint16 {
	var sum uint32
	for i := 0; i < 20; i += 2 {
		sum += uint32(binary.BigEndian.Uint16(b[i : i+2]))
	}
	for sum > 0xffff {
		sum = (sum >> 16) + (sum & 0xffff)
	}
	return uint16(^sum)
}

// validateChecksum reports whether the header checksum is correct.
func validateChecksum(b []byte) bool {
	return computeChecksum(b) == 0
}

// dropPacket decides whether to drop a packet based on protocol and TTL.
func dropPacket(h packetHeader) bool {
	return h.protocol == 6 && h.ttl < 64
}

func main() {
	// Craft a packet with a deliberately bad checksum to test the filter.
	raw := []byte{
		0x45, 0x00, 0x00, 0x3c, 0x1c, 0x46, 0x40, 0x00,
		0x40, 0x06, 0x00, 0x00, 0x0a, 0x00, 0x00, 0x01,
		0x0a, 0x00, 0x00, 0x02,
	}
	h := parseHeader(raw)
	fmt.Printf("header: %+v\n", h)
	fmt.Printf("checksum valid: %v\n", validateChecksum(raw))
	fmt.Printf("drop? %v\n", dropPacket(h))
	fmt.Printf("src: %s\n", net.IP(h.srcIP[:]).String())
	fmt.Printf("dst: %s\n", net.IP(h.dstIP[:]).String())
}

