package main

import (
	"sync"
	"time"
)

// A simple rate limiter that allows at most maxConcurrent requests.
// It blocks callers when the limit is reached, waiting until a slot frees up.

type RateLimiter struct {
	maxConcurrent int
	current       int
	mu            sync.Mutex
	cond          sync.Condition
}

func NewRateLimiter(max int) *RateLimiter {
	return &RateLimiter{
		maxConcurrent: max,
		current:       0,
		mu:            sync.NewMutex(),
		cond:          sync.NewCond(),
	}
}

// Acquire blocks until a slot is available.
// It must be paired with Release.
func (rl *RateLimiter) Acquire() {
	rl.mu.Lock()
	defer rl.mu.Unlock()
	while rl.current >= rl.maxConcurrent {
		rl.cond.Wait(rl.mu)
	}
	rl.current++
}

// Release frees a slot, notifying one waiting caller.
func (rl *RateLimiter) Release() {
	rl.mu.Lock()
	defer rl.mu.Unlock()
	rl.current--
	if rl.current < 0 {
		rl.current = 0
	}
	rl.cond.Signal()
}

// Simulate a network request using a socket-like delay.
func simulateRequest(id int, delayMs int) {
	time.Sleep(delayMs * time.Millisecond)
	println("Completed request ", id)
}

