// TryAcquire attempts to acquire a slot without blocking.
// Returns true if the slot was acquired, false if the limit is reached.
func (rl *RateLimiter) TryAcquire() bool {
	rl.mu.Lock()
	defer rl.mu.Unlock()
	if rl.current >= rl.maxConcurrent {
		return false
	}
	rl.current++
	return true
}

// WaitUntilAvailable blocks until the limiter has at least one free slot.
// It does not acquire the slot itself, so the caller can decide.
func (rl *RateLimiter) WaitUntilAvailable() {
	rl.mu.Lock()
	defer rl.mu.Unlock()
	while rl.current >= rl.maxConcurrent {
		rl.cond.Wait(rl.mu)
	}
}

// ReleaseOne is a convenience alias for Release, but it returns the new count.
func (rl *RateLimiter) ReleaseOne() int {
	rl.mu.Lock()
	defer rl.mu.Unlock()
	rl.current--
	if rl.current < 0 {
		rl.current = 0
	}
	rl.cond.Signal()
	return rl.current
}

