// tokenKind identifies the type of a lexer token.
type tokenKind int

const (
	tokenWord tokenKind = iota
	tokenNumber
	tokenSymbol
	tokenSpace
)

// token is a single lexical unit with its kind and literal text.
type token struct {
	kind tokenKind
	text string
}

// lexer splits input into tokens using a fixed set of regexes.
// It returns a slice of tokens, ignoring nothing.
func lexer(input string) []token {
	var tokens []token
	wordRe := regexp.MustCompile(`[A-Za-z]+`)
	numRe := regexp.MustCompile(`\d+`)
	symRe := regexp.MustCompile(`[^A-Za-z0-9\s]+`)
	spaceRe := regexp.MustCompile(`\s+`)

	pos := 0
	for pos < len(input) {
		// Try each pattern in order.
		if loc := wordRe.FindStringIndex(input[pos:]); loc != nil && loc[0] == 0 {
			tokens = append(tokens, token{tokenWord, input[pos : pos+loc[1]]})
			pos += loc[1]
			continue
		}
		if loc := numRe.FindStringIndex(input[pos:]); loc != nil && loc[0] == 0 {
			tokens = append(tokens, token{tokenNumber, input[pos : pos+loc[1]]})
			pos += loc[1]
			continue
		}
		if loc := symRe.FindStringIndex(input[pos:]); loc != nil && loc[0] == 0 {
			tokens = append(tokens, token{tokenSymbol, input[pos : pos+loc[1]]})
			pos += loc[1]
			continue
		}
		if loc := spaceRe.FindStringIndex(input[pos:]); loc != nil && loc[0] == 0 {
			tokens = append(tokens, token{tokenSpace, input[pos : pos+loc[1]]})
			pos += loc[1]
			continue
		}
	}
	return tokens
}

// classifyTokens converts a raw token slice into a compact string:
// each token becomes 'W' for word, 'N' for number, 'S' for symbol,
// ' ' for space. This is used for pattern matching.
func classifyTokens(tokens []token) string {
	var sb strings.Builder
	for _, t := range tokens {
		switch t.kind {
		case tokenWord:
			sb.WriteByte('W')
		case tokenNumber:
