package main

import "fmt"

// visited states: 0=unvisited, 1=in current path, 2=fully processed
var state []int
var order []int
var hasCycle bool

func dfs(node int, graph [][]int) {
    state[node] = 1
    for _, next := range graph[node] {
        if state[next] == 0 {
            dfs(next, graph)
        } else if state[next] == 1 {
            hasCycle = true
            return
        }
        if hasCycle {
            return
        }
    }
    state[node] = 2
    order = append(order, node)
}

func topoSort(n int, graph [][]int) ([]int, bool) {
    state = make([]int, n)
    order = []int{}
    hasCycle = false
    for i := 0; i < n; i++ {
        if state[i] == 0 {
            dfs(i, graph)
            if hasCycle {
                return nil, false
            }
        }
    }
    return order, true
}

func main() {
    // Graph: 0->1, 0->2, 1->3, 2->3, 3->4
    graph := [][]int{
        {1, 2},
        {3},
        {3},
        {4},
        {},
    }
    result, ok := topoSort(5, graph)
    if !ok {
        fmt.Println("cycle")
        return
