function jacobiEigen(A, tol = 1e-10) {
  const n = A.length;
  let V = Array.from({length: n}, (_, i) => {
    const row = new Array(n).fill(0);
    row[i] = 1;
    return row;
  });
  let maxOff = 0;
  do {
    maxOff = 0;
    let p = 0, q = 1;
    for (let i = 0; i < n; i++) {
      for (let j = i + 1; j < n; j++) {
        if (Math.abs(A[i][j]) > maxOff) { maxOff = Math.abs(A[i][j]); p = i; q = j; }
      }
    }
    if (maxOff < tol) break;
    const theta = (A[q][q] - A[p][p]) / (2 * A[p][q]);
    const t = Math.sign(theta) / (Math.abs(theta) + Math.sqrt(theta * theta + 1));
    const c = 1 / Math.sqrt(t * t + 1);
    const s = t * c;
    for (let k = 0; k < n; k++) {
      const akp = A[k][p]; const akq = A[k][q];
      A[k][p] = c * akp - s * akq;
      A[k][q] = s * akp + c * akq;
    }
    for (let k = 0; k < n; k++) {
      const apk = A[p][k]; const aqk = A[q][k];
      A[p][k] = c * apk - s * aqk;
      A[q][k] = s * apk + c * aqk;
    }
    for (let k = 0; k < n; k++) {
      const vkp = V[k][p]; const vkq = V[k][q];
      V[k][p] = c * vkp - s * vkq;
      V[k][q] = s * vkp + c * vkq;
    }
  } while (maxOff >= tol);
  const eigenvalues = [];
  for (let i = 0; i < n; i++) eigenvalues.push(A[i][i]);
  return { eigenvalues, eigenvectors: V };
}

function checkOrthogonal(V, tol = 1e-8) {
  const n = V.length;
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) {
      let dot = 0;
      for (let k = 0; k < n; k++) dot += V[k][i] * V[k][j];
      if (Math.abs(dot - (i === j ? 1 : 0)) > tol) return false;
    }
  }
  return true;
}

