package main

import (
	"bytes"
	"encoding/binary"
	"fmt"
	"reflect"
	"strings"
)

// CustomEncoder encodes structs with tagged fields into a compact binary format.
// Tag format: `enc:"type"` where type is one of: u8, u16, u32, i8, i16, i32.
type CustomEncoder struct {
	buf bytes.Buffer
}

func (e *CustomEncoder) Encode(v interface{}) error {
	rv := reflect.ValueOf(v)
	if rv.Kind() != reflect.Ptr || rv.Elem().Kind() != reflect.Struct {
		return fmt.Errorf("expected pointer to struct")
	}
	rv = rv.Elem()
	for i := 0; i < rv.NumField(); i++ {
		field := rv.Type().Field(i)
		tag := field.Tag.Get("enc")
		if tag == "" {
			continue
		}
		fv := rv.Field(i)
		switch tag {
		case "u8":
			e.buf.WriteByte(byte(fv.Uint()))
		case "u16":
			binary.Write(&e.buf, binary.LittleEndian, uint16(fv.Uint()))
		case "u32":
			binary.Write(&e.buf, binary.LittleEndian, uint32(fv.Uint()))
		case "i8":
			e.buf.WriteByte(byte(int8(fv.Int())))
		case "i16":
			binary.Write(&e.buf, binary.LittleEndian, int16(fv.Int()))
		case "i32":
			binary.Write(&e.buf, binary.LittleEndian, int32(fv.Int()))
		default:
			return fmt.Errorf("unknown tag %q", tag)
		}
	}
	return nil
}

func (e *CustomEncoder) Bytes() []byte {
	return e.buf.Bytes()
}

func parseTag(tag string) (string, error) {
	parts := strings.Split(tag, ",")
	if len(parts) != 2 {
		return "", fmt.Errorf("tag must have exactly two parts")
	}
	if parts[0] != "enc" {
		return "", fmt.Errorf("tag must start with enc")
	}
	return parts[1], nil
}

// Decode reads from a byte slice into a struct using the same tags.
func Decode(data []byte, v interface{}) error {
	rv := reflect.ValueOf(v)
	if rv.Kind() != reflect.Ptr || rv.Elem().Kind() != reflect.Struct {
		return fmt.Errorf("expected pointer to struct")
	}
	rv = rv.Elem()
	rt := rv.Type()
	pos := 0
	for i := 0; i < rv.NumField(); i++ {
		field := rt.Field(i)
		tag := field.Tag.Get("enc")
		if tag == "" {
			continue
		}
		typ, err := parseTag(tag)
		if err != nil {
			return err
		}
		fv := rv.Field(i)
		var size int
		switch typ {
		case "u8", "i8":
			size = 1
		case "u16", "i16":
			size = 2
		case "u32", "i32":
			size = 4
		default:
			return fmt.Errorf("unknown type %q", typ)
		}
		if pos+size > len(data) {
			return fmt.Errorf("buffer too short")
		}
		// The hole is here: the entire switch that reads the values.
		pos += size
	}
	return nil
}

