	Temperature int32 `enc:"i32"`
	Humidity    uint8 `enc:"u8"`
	Pressure    uint16 `enc:"u16"`
}

func main() {
	s := &SensorReading{Temperature: -12345, Humidity: 200, Pressure: 65535}
	e := &CustomEncoder{}
	if err := e.Encode(s); err != nil {
		panic(err)
	}
	data := e.Bytes()
