import threading
import weakref

class Registry:
    _instance = None
    _lock = threading.Lock()
    def __new__(cls):
        if cls._instance is None:
            with cls._lock:
                if cls._instance is None:
                    cls._instance = super().__new__(cls)
                    cls._instance._objects = weakref.WeakSet()
        return cls._instance
    def register(self, obj):
        self._objects.add(obj)
    def get_all(self):
        return list(self._objects)

class ManagedResource:
    _active = set()
    _registry = Registry()
    _shutdown = False
    def __init__(self, name):
        self.name = name
        self._refcount = 1
        self._finalizer = weakref.finalize(self, self._cleanup, name)
        ManagedResource._active.add(self)
        self._registry.register(self)
    @classmethod
    def shutdown_all(cls):
        cls._shutdown = True
        for obj in list(cls._active):
            obj.release()
    def acquire(self):
        if ManagedResource._shutdown:
            raise RuntimeError("shutdown in progress")
        self._refcount += 1
        return self
    def release(self):
        if self._refcount <= 0:
            return
        self._refcount -= 1
        if self._refcount == 0:
            self._finalizer()
            ManagedResource._active.discard(self)
    def _cleanup(self):
        print(f"Cleaning {self}")
    def __repr__(self):
        return f"<Resource {self.name} refs={self._refcount}>"

