#define MAX_NAME 32

typedef struct {
    uint32_t id;
    char name[MAX_NAME];
    uint16_t flags;
    uint32_t payload_size;
    uint8_t payload[256];
} Record;

static void serialize_u32(FILE *f, uint32_t v) {
    fputc((v >> 24) & 0xFF, f);
    fputc((v >> 16) & 0xFF, f);
    fputc((v >> 8) & 0xFF, f);
    fputc(v & 0xFF, f);
}

static void serialize_u16(FILE *f, uint16_t v) {
    fputc((v >> 8) & 0xFF, f);
    fputc(v & 0xFF, f);
}

static int write_record(const Record *rec, FILE *f) {
    if (!rec || !f) return -1;
    if (rec->payload_size > sizeof(rec->payload)) return -1;
    serialize_u32(f, rec->id);
    fwrite(rec->name, 1, MAX_NAME, f);
    serialize_u16(f, rec->flags);
    serialize_u32(f, rec->payload_size);
    fwrite(rec->payload, 1, rec->payload_size, f);
    return 0;
}

