const (
	serverAddr = "localhost:8080"
	connTimeout = 2 * time.Second
	readTimeout = 1 * time.Second
)

func handleConn(ctx context.Context, conn net.Conn) error {
	defer conn.Close()
	buf := make([]byte, 1024)
	for {
		select {
		case <-ctx.Done():
			return ctx.Err()
		default:
		}
		conn.SetReadDeadline(time.Now().Add(readTimeout))
		n, err := conn.Read(buf)
		if err != nil {
			if ne, ok := err.(net.Error); ok && ne.Timeout() {
				continue
			}
			return err
		}
		if n == 0 {
			return nil
		}
		fmt.Printf("received: %s\n", string(buf[:n]))
	}
}

func acceptLoop(ctx context.Context, ln net.Listener) error {
	for {
		conn, err := ln.Accept()
		if err != nil {
			select {
			case <-ctx.Done():
				return ctx.Err()
			default:
				return err
			}
		}
		go func(c net.Conn) {
			if err := handleConn(ctx, c); err != nil {
				fmt.Printf("conn error: %v\n", err)
			}
		}(conn)
	}
}

