// maxIdle is the maximum duration a connection can stay idle.
const maxIdle = 5 * time.Second

// dialContext dials a TCP connection with a timeout.
func dialContext(ctx context.Context, addr string) (net.Conn, error) {
	d := net.Dialer{Timeout: 2 * time.Second}
	return d.DialContext(ctx, "tcp", addr)
}

// handleConn reads a single line and writes a response.
func handleConn(conn net.Conn) {
	defer conn.Close()
	buf := make([]byte, 1024)
	for {
		conn.SetReadDeadline(time.Now().Add(maxIdle))
		n, err := conn.Read(buf)
		if err != nil {
			return
		}
		line := string(buf[:n])
		if line == "ping" {
			conn.Write([]byte("pong\n"))
		} else {
			conn.Write([]byte("unknown\n"))
		}
	}
}

// serve accepts connections and spawns a goroutine per connection.
func serve(ctx context.Context, ln net.Listener, wg *sync.WaitGroup) {
	defer wg.Done()
	for {
		conn, err := ln.Accept()
		if err != nil {
			select {
			case <-ctx.Done():
				return
			default:
				continue
			}
		}
		wg.Add(1)
		go func() {
			defer wg.Done()
			handleConn(conn)
		}()
	}
}

