func main() {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	ln, err := net.Listen("tcp", ":8080")
	if err != nil {
		panic(err)
	}
	defer ln.Close()

	var wg sync.WaitGroup
	wg.Add(1)
	go serve(ctx, ln, &wg)

	// Wait for a signal to shut down (simulated by a timer).
	go func() {
		time.Sleep(10 * time.Second)
		cancel()
	}()

	wg.Wait()
	fmt.Println("server stopped")
}

