const INF = int(1e9)

type Edge struct {
	from, to, weight int
}

func shortestPathWithNegativeEdges(n int, edges []Edge, source int) ([]int, bool) {
	dist := make([]int, n)
	for i := range dist {
		dist[i] = INF
	}
	dist[source] = 0

	for i := 0; i < n-1; i++ {
		updated := false
		for _, e := range edges {
			if dist[e.from] != INF && dist[e.from]+e.weight < dist[e.to] {
				dist[e.to] = dist[e.from] + e.weight
				updated = true
			}
		}
		if !updated {
			break
		}
	}

	// Detect negative cycles
	for _, e := range edges {
		if dist[e.from] != INF && dist[e.from]+e.weight < dist[e.to] {
			return nil, true
		}
	}
	return dist, false
}

