const maxWorkers = 3

type WorkItem struct {
	ID int
}

func worker(ctx context.Context, id int, wg *sync.WaitGroup, jobs <-chan WorkItem, results chan<- error) {
	defer wg.Done()
	for {
		select {
		case <-ctx.Done():
			return
		case job, ok := <-jobs:
			if !ok {
				return
			}
			// Simulate work
			time.Sleep(20 * time.Millisecond)
			if job.ID%2 == 0 {
				results <- fmt.Errorf("job %d failed", job.ID)
			} else {
				results <- nil
			}
		}
	}
}

func run(ctx context.Context, jobs []WorkItem) []error {
	var wg sync.WaitGroup
	jobsCh := make(chan WorkItem)
	resultsCh := make(chan error, len(jobs))

	// Start workers
	for i := 0; i < maxWorkers; i++ {
		wg.Add(1)
		go worker(ctx, i, &wg, jobsCh, resultsCh)
	}

	// Send jobs
	go func() {
		defer close(jobsCh)
		for _, j := range jobs {
			select {
			case <-ctx.Done():
				return
			case jobsCh <- j:
			}
		}
	}()

	// Wait for workers to finish and then close results
	go func() {
		wg.Wait()
		close(resultsCh)
	}()

	// Collect results
	var errs []error
	for err := range resultsCh {
		if err != nil {
			errs = append(errs, err)
		}
	}
	return errs
}

