#include <stddef.h>
#include <stdint.h>

typedef struct {
    uint8_t *base;
    size_t capacity;
    size_t head;
    size_t tail;
    int full;
} circ_buf;

void circ_init(circ_buf *cb, void *storage, size_t size) {
    uintptr_t addr = (uintptr_t)storage;
    size_t align = sizeof(uint64_t);
    size_t misalign = (align - (addr % align)) % align;
    cb->base = (uint8_t *)storage + misalign;
    cb->capacity = (size - misalign) / align * align;
    cb->head = 0;
    cb->tail = 0;
    cb->full = 0;
}

static uint8_t *cb_at(const circ_buf *cb, size_t index) {
    return cb->base + (index % cb->capacity);
}

void circ_push(circ_buf *cb, const void *data, size_t len) {
    if (len > cb->capacity) return;
    if (cb->full && len > 0) {
        cb->head = (cb->head + len) % cb->capacity;
    }
    for (size_t i = 0; i < len; i++) {
        *cb_at(cb, (cb->tail + i) % cb->capacity) = ((const uint8_t *)data)[i];
    }
    cb->tail = (cb->tail + len) % cb->capacity;
    if (len > 0 && cb->tail == cb->head) cb->full = 1;
}

void circ_pop(circ_buf *cb, void *data, size_t len) {
    if (len > cb->capacity) return;
    if (cb->full) cb->full = 0;
    for (size_t i = 0; i < len; i++) {
        ((uint8_t *)data)[i] = *cb_at(cb, (cb->head + i) % cb->capacity);
    }
    cb->head = (cb->head + len) % cb->capacity;
    if (len > 0 && cb->head == cb->tail && !cb->full) cb->full = 0;
}

size_t circ_used(const circ_buf *cb) {
    if (cb->full) return cb->capacity;
    if (cb->tail >= cb->head) return cb->tail - cb->head;
    return cb->capacity - cb->head + cb->tail;
}

size_t circ_free(const circ_buf *cb) {
    return cb->capacity - circ_used(cb);
}

void circ_compact(circ_buf *cb) {
    size_t used = circ_used(cb);
    if (used == 0) {
        cb->head = cb->tail = 0;
        cb->full = 0;
        return;
    }
    if (cb->head == 0) return;
    for (size_t i = 0; i < used; i++) {
        cb->base[i] = *cb_at(cb, (cb->head + i) % cb->capacity);
    }
    cb->head = 0;
    cb->tail = used % cb->capacity;
    cb->full = (used == cb->capacity) ? 1 : 0;
}

