package main

import "fmt"

const n = 10

type BIT []int

func newBIT(size int) BIT {
	return make(BIT, size+1)
}

func (b BIT) update(idx int, delta int) {
	for i := idx; i <= n; i += i & (-i) {
		b[i] += delta
	}
}

func (b BIT) query(idx int) int {
	sum := 0
	for i := idx; i > 0; i -= i & (-i) {
		sum += b[i]
	}
	return sum
}

func (b BIT) rangeSum(l, r int) int {
	return b.query(r) - b.query(l-1)
}

