package main

import (
	"fmt"
	"strings"
	"unicode"
)

// tokenize splits s into words, preserving order, using f to decide separators.
func tokenize(s string, f func(rune) bool) []string {
	return strings.FieldsFunc(s, f)
}

// isSeparator reports whether r is a punctuation or space.
func isSeparator(r rune) bool {
	return unicode.IsPunct(r) || unicode.IsSpace(r)
}

// normalize converts a word to lowercase and removes leading/trailing punctuation.
func normalize(word string) string {
	return strings.Trim(strings.ToLower(word), ".,!?;:()[]{}'\"")
}

// summarize processes the input text and returns a summary line.
func summarize(text string) string {
	words := tokenize(text, isSeparator)
	if len(words) == 0 {
		return ""
	}
	counts := make(map[string]int)
	for _, w := range words {
		nw := normalize(w)
		if nw != "" {
			counts[nw]++
		}
	}
	maxCount := 0
	mostFreq := ""
	for w, c := range counts {
		if c > maxCount {
			maxCount = c
			mostFreq = w
		}
	}
	// Build the summary: most frequent word and its count.
	return fmt.Sprintf("%s:%d", mostFreq, maxCount)
}

