const fs = require('fs').promises;
const path = require('path');

const ROOT = process.env.DATA_ROOT || './data';

// Recursively list all files in a directory, filtering by extension.
async function listFiles(dir, ext) {
  const entries = await fs.readdir(dir, { withFileTypes: true });
  const files = [];
  for (const entry of entries) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      files.push(...await listFiles(full, ext));
    } else if (entry.isFile() && entry.name.endsWith(ext)) {
      files.push(full);
    }
  }
  return files;
}

// Gather contents of all matching files into a single object.
async function gatherFiles(ext) {
  const files = await listFiles(ROOT, ext);
  const contents = {};
  for (const file of files) {
    const rel = path.relative(ROOT, file);
    contents[rel] = await fs.readFile(file, 'utf8');
  }
  return contents;
}

// Compute a simple hash of a file's contents (for change detection).
function hashContent(str) {
  let hash = 0;
  for (let i = 0; i < str.length; i++) {
    hash = ((hash << 5) - hash + str.charCodeAt(i)) | 0;
  }
  return hash.toString(36);
}

// Write a backup of the gathered files to a timestamped directory.
// Return the backup directory path.
// If the input is null, throw an error.
async function createBackup(contents) {
  if (!contents) throw new Error('No contents provided');
  const stamp = new Date().toISOString().replace(/[:.]/g, '-');
  const backupDir = path.join(ROOT, 'backups', stamp);
  await fs.mkdir(backupDir, { recursive: true });
  for (const [rel, data] of Object.entries(contents)) {
    const dest = path.join(backupDir, rel);
    await fs.mkdir(path.dirname(dest), { recursive: true });
    await fs.writeFile(dest, data);
  }
  return backupDir;
}

// Main function: gather all .txt files, compute hashes, detect duplicates,
// create a backup, and report.
async function main() {
  const ext = '.txt';
  const contents = await gatherFiles(ext);
  const hashes = {};
  const duplicates = [];
  for (const [rel, data] of Object.entries(contents)) {
    const h = hashContent(data);
    if (hashes[h]) {
      duplicates.push([hashes[h], rel]);
    } else {
      hashes[h] = rel;
    }
  }
  if (duplicates.length > 0) {
    console.log('Duplicate files found:', duplicates);
  }

  const backupDir = await createBackup(contents);
  console.log('Backup created at', backupDir);
  console.log('Total files:', Object.keys(contents).length);
}

main().catch(err => {
  console.error('Fatal error:', err);
  process.exit(1);
});

