const backoffMs = [200, 500, 1000];

async function fetchWithRetry(url, attemptsLeft = MAX_ATTEMPTS) {
  try {
    const res = await fetch(url);
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    return res.json();
  } catch (err) {
    if (attemptsLeft <= 1) throw err;
    const attempt = MAX_ATTEMPTS - attemptsLeft + 1;
    await new Promise(resolve => setTimeout(resolve, backoffMs[attempt - 1]));
    return fetchWithRetry(url, attemptsLeft - 1);
  }
}

