import re

def tokenize(text):
    # Simple tokenizer: words, numbers, and punctuation
    return re.findall(r'[A-Za-z]+|\d+|[^\s]', text)

def process(tokens):
    # Recursive descent parser for a simple grammar:
    #   expression := term (('+'|'-') term)*
    #   term       := factor (('*'|'/') factor)*
    #   factor     := number | '(' expression ')'
    pos = 0
    def parse_expression():
        nonlocal pos
        value = parse_term()
        while pos < len(tokens) and tokens[pos] in ('+', '-'):
            op = tokens[pos]
            pos += 1
            rhs = parse_term()
            if op == '+':
                value += rhs
            else:
                value -= rhs
        return value
    def parse_term():
        nonlocal pos
        value = parse_factor()
        while pos < len(tokens) and tokens[pos] in ('*', '/'):
            op = tokens[pos]
            pos += 1
            rhs = parse_factor()
            if op == '*':
                value *= rhs
            else:
                value /= rhs
        return value
    def parse_factor():
        nonlocal pos
        token = tokens[pos]
        if token == '(':
            pos += 1
            val = parse_expression()
            if tokens[pos] != ')':
                raise ValueError('Mismatched parentheses')
            pos += 1
            return val
        elif token.isdigit():
            pos += 1
            return float(token)
        else:
            raise ValueError(f'Unexpected token: {token}')
    result = parse_expression()
    if pos != len(tokens):
        raise ValueError('Unexpected trailing tokens')
    return result

