package main

import (
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

const rootDir = "./data"

// hashFile computes the SHA-256 hash of a file's contents.
func hashFile(path string) (string, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return "", err
	}
	sum := sha256.Sum256(data)
	return hex.EncodeToString(sum[:]), nil
}

// scanDirectory walks the directory tree and collects hashes of all files.
func scanDirectory() (map[string]string, error) {
	hashes := make(map[string]string)
	err := filepath.Walk(rootDir, func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return err
		}
		if info.IsDir() {
			return nil
		}
		hash, err := hashFile(path)
		if err != nil {
			return err
		}
		hashes[path] = hash
		return nil
	})
	if err != nil {
		return nil, err
	}
	return hashes, nil
}

// findDuplicateHashes returns a map from hash to list of file paths with that hash.
func findDuplicateHashes(hashes map[string]string) map[string][]string {
	duplicates := make(map[string][]string)
	for path, hash := range hashes {
		duplicates[hash] = append(duplicates[hash], path)
	}
	for hash, paths := range duplicates {
		if len(paths) < 2 {
			delete(duplicates, hash)
		}
	}
	return duplicates
}

// printDuplicates prints each hash and the files that share it.
func printDuplicates(dups map[string][]string) {
	for hash, paths := range dups {
		fmt.Printf("Hash: %s\n", hash)
		for _, p := range paths {
			fmt.Printf("  %s\n", p)
		}
	}
}

// removeDuplicates deletes all but the first file for each duplicate hash.
func removeDuplicates(dups map[string][]string) error {
	for _, paths := range dups {
		for i := 1; i < len(paths); i++ {
			if err := os.Remove(paths[i]); err != nil {
				return err
			}
		}
	}
	return nil
}

func main() {
	hashes, err := scanDirectory()
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error scanning: %v\n", err)
		os.Exit(1)
	}
	dups := findDuplicateHashes(hashes)
	if len(dups) == 0 {
		fmt.Println("No duplicate files found.")
		return
	}
	fmt.Println("Duplicate files found:")
	printDuplicates(dups)
	fmt.Println("\nDeleting duplicates...")
	if err := removeDuplicates(dups); err != nil {
		fmt.Fprintf(os.Stderr, "Error deleting: %v\n", err)
		os.Exit(1)
	}
	fmt.Println("Remaining files:")
	remaining, _ := scanDirectory()
	for path := range remaining {
		fmt.Println(path)
	}
}

