    int left = parse_factor();
    if (left < 0) return -1;
    while (1) {
        skip_ws();
        char op = input[pos];
        if (op == '*' || op == '/') {
            pos++;
            int right = parse_factor();
            if (right < 0) return -1;
            if (op == '*') left *= right;
            else if (right == 0) return -1;
            else left /= right;
        } else break;
    }
    return left;
}

static int parse_expr(void) {
    int left = parse_term();
    if (left < 0) return -1;
    while (1) {
        skip_ws();
        char op = input[pos];
