package main

import (
	"container/heap"
	"fmt"
)

// Item holds a value and its priority.
type Item struct {
	value    string
	priority int
	index    int // index in the heap, maintained by heap.Interface
}

// priorityQueue implements heap.Interface and holds Items.
type priorityQueue []*Item

func (pq priorityQueue) Len() int { return len(pq) }

func (pq priorityQueue) Less(i, j int) bool {
	// We want Pop to give us the highest, not lowest, priority so we use greater than here.
	return pq[i].priority > pq[j].priority
}

func (pq priorityQueue) Swap(i, j int) {
	pq[i], pq[j] = pq[j], pq[i]
	pq[i].index = i
	pq[j].index = j
}

func (pq *priorityQueue) Push(x interface{}) {
	n := len(*pq)
	item := x.(*Item)
	item.index = n
	*pq = append(*pq, item)
}

func (pq *priorityQueue) Pop() interface{} {
	old := *pq
	n := len(old)
	item := old[n-1]
	old[n-1] = nil // avoid memory leak
	item.index = -1
	*pq = old[0 : n-1]
	return item
}

// update modifies the priority and value of an Item in the queue.
func (pq *priorityQueue) update(item *Item, value string, priority int) {
	item.value = value
	item.priority = priority
	heap.Fix(pq, item.index)
}

func main() {
	// Create a priority queue and put some items in it.
	pq := &priorityQueue{}
	heap.Init(pq)
	heap.Push(pq, &Item{value: "banana", priority: 3})
	heap.Push(pq, &Item{value: "apple", priority: 1})
	heap.Push(pq, &Item{value: "pear", priority: 4})

	// Take the items out; they arrive in decreasing priority order.
	for pq.Len() > 0 {
		item := heap.Pop(pq).(*Item)
		fmt.Printf("%.2d:%s ", item.priority, item.value)
	}
	fmt.Println()

	// Recreate a queue, push items, and update one.
	pq = &priorityQueue{}
	heap.Init(pq)
	heap.Push(pq, &Item{value: "orange", priority: 2})
	heap.Push(pq, &Item{value: "grape", priority: 5})
	item := &Item{value: "cherry", priority: 3}
	heap.Push(pq, item)

	// Update the priority of "cherry" to 6.
	pq.update(item, "cherry", 6)

	// Take them out again.
	for pq.Len() > 0 {
		item := heap.Pop(pq).(*Item)
		fmt.Printf("%.2d:%s ", item.priority, item.value)
	}
	fmt.Println()
