// costToReach returns the minimum time to travel from node 'from' to node 'to'
// in the given graph, using the provided edge costs. The graph is represented
// as an adjacency list where each edge has a cost.
func costToReach(graph [][]Edge, from, to int, memo []int) int {
	if from == to {
		return 0
	}
	if memo[from] != -1 {
		return memo[from]
	}
	best := 1 << 30
	for _, e := range graph[from] {
		c := e.cost + costToReach(graph, e.to, to, memo)
		if c < best {
			best = c
		}
	}
	memo[from] = best
	return best
}

