package main

import (
	"fmt"
	"math"
)

// taylorSinApprox computes sin(x) using a Taylor series expansion around 0,
// stopping when the absolute value of the next term is below epsilon.
// It returns the approximation and the number of terms used.
func taylorSinApprox(x float64, epsilon float64) (float64, int) {
	term := x
	sum := x
	n := 1
	for math.Abs(term) > epsilon && n < 100 {
		term *= -x * x / float64((2*n)*(2*n+1))
		sum += term
		n++
	}
	return sum, n
}

// taylorCosApprox computes cos(x) using a Taylor series expansion around 0,
// stopping when the absolute value of the next term is below epsilon.
func taylorCosApprox(x float64, epsilon float64) (float64, int) {
	term := 1.0
	sum := 1.0
	n := 1
	for math.Abs(term) > epsilon && n < 100 {
		term *= -x * x / float64((2*n-1)*(2*n))
		sum += term
		n++
	}
	return sum, n
}

// taylorExpApprox computes e^x using a Taylor series expansion around 0.
func taylorExpApprox(x float64, epsilon float64) (float64, int) {
	term := 1.0
	sum := 1.0
	n := 1
	for math.Abs(term) > epsilon && n < 100 {
		term *= x / float64(n)
		sum += term
		n++
	}
	return sum, n
}

// sinCosProductApprox computes sin(x)*cos(x) using the identity sin(2x)/2.
// It uses the Taylor approximations from above for sin and cos of 2x.
// The function returns the approximation and the total number of terms used
// from both series combined.
func sinCosProductApprox(x float64, epsilon float64) (float64, int) {
	// Use the identity: sin(x)*cos(x) = sin(2x)/2
	sinVal, sinTerms := taylorSinApprox(2*x, epsilon/10)
	cosVal, cosTerms := taylorCosApprox(2*x, epsilon/10)

	// Compute sin(2x) using the series directly for comparison.
	sin2xDirect, _ := taylorSinApprox(2*x, epsilon/10)

	// Compute the product directly using the individual series.
	directProduct := sinVal * cosVal

	// Compute the product using the identity.
	identityProduct := sin2xDirect / 2.0

	// Return the identity product and total terms.
	return identityProduct, sinTerms + cosTerms
}

func main() {
	// Test values
	x := 0.3
	eps := 1e-8

	// Compute using the approximation function
	approx, terms := sinCosProductApprox(x, eps)

	// Compute using math library for comparison
	expected := math.Sin(x) * math.Cos(x)

	// Print results
	fmt.Printf("Approx: %.10f\n", approx)
	fmt.Printf("Expected: %.10f\n", expected)
	fmt.Printf("Terms used: %d\n", terms)
}

