package main

import (
	"fmt"
)

const maxNodes = 100

var adjacency [maxNodes][maxNodes]bool
var visited [maxNodes]int // 0=unvisited, 1=in-progress, 2=done
var order []int

func dfs(node int) bool {
	if visited[node] == 1 {
		return false
	}
	if visited[node] == 2 {
		return true
	}
	visited[node] = 1
	for next := 0; next < maxNodes; next++ {
		if adjacency[node][next] {
			if !dfs(next) {
				return false
			}
		}
	}
	visited[node] = 2
	order = append(order, node)
	return true
}

func topoSort(n int) ([]int, bool) {
	for i := 0; i < n; i++ {
		if visited[i] == 0 {
			if !dfs(i) {
				return nil, false
			}
		}
	}
	return order, true
}

