const EventEmitter = require('events');

class ResourceManager extends EventEmitter {
  constructor() {
    super();
    this.resources = new Map();
    this.allocated = 0;
    this.max = 5;
  }

  allocate(id) {
    if (this.allocated >= this.max) {
      this.emit('error', new Error('limit reached'));
      return false;
    }
    this.resources.set(id, { inUse: true });
    this.allocated++;
    return true;
  }

  release(id) {
    if (this.resources.has(id)) {
      this.resources.get(id).inUse = false;
      this.allocated--;
      this.emit('release', id);
    }
  }

  cleanup() {
    for (const [id, res] of this.resources) {
      if (!res.inUse) {
        this.resources.delete(id);
      }
    }
    this.emit('cleanup', this.resources.size);
  }
}

