package main

import (
	"fmt"
	"strconv"
	"strings"
)

type token struct {
	kind string // "num", "op", "lparen", "rparen"
	val  string
}

func tokenize(s string) []token {
	var tokens []token
	i := 0
	for i < len(s) {
		c := s[i]
		switch {
		case c == ' ':
			i++
		case c >= '0' && c <= '9':
			j := i
			for j < len(s) && s[j] >= '0' && s[j] <= '9' {
				j++
			}
			tokens = append(tokens, token{"num", s[i:j]})
			i = j
		case c == '+' || c == '-' || c == '*' || c == '/':
			tokens = append(tokens, token{"op", string(c)})
			i++
		case c == '(':
			tokens = append(tokens, token{"lparen", "("})
			i++
		case c == ')':
			tokens = append(tokens, token{"rparen", ")"})
			i++
		default:
			panic("bad token")
		}
	}
	return tokens
}

func parse(tokens []token) int {
	pos := 0
	var parseExpr func(int) int
	parseExpr = func(minPrec int) int {
		if pos >= len(tokens) {
			panic("unexpected end")
		}
		left := 0
		if tokens[pos].kind == "num" {
			left, _ = strconv.Atoi(tokens[pos].val)
			pos++
		} else if tokens[pos].kind == "lparen" {
			pos++
			left = parseExpr(1)
			if pos >= len(tokens) || tokens[pos].kind != "rparen" {
				panic("missing rparen")
			}
			pos++
		} else {
			panic("expected number or paren")
		}
		for pos < len(tokens) && tokens[pos].kind == "op" {
			op := tokens[pos].val
			prec := 0
			switch op {
			case "+", "-":
				prec = 1
			case "*", "/":
				prec = 2
			}
			if prec < minPrec {
				break
			}
			pos++
			right := parseExpr(prec + 1)
			switch op {
			case "+":
				left += right
			case "-":
				left -= right
			case "*":
				left *= right
			case "/":
				left /= right
			}
		}
		return left
	}
	result := parseExpr(1)
	if pos != len(tokens) {
		panic("trailing tokens")
	}
	return result
}

// The hole: a function that evaluates an expression string.
// It must use the tokenizer and parser defined above.
// It must handle the fact that the parser expects tokens from tokenize.
// It must return the integer result.

func main() {
	exprs := []string{"2+3*4", "(1+2)*3", "10-2-3", "20/4/2"}
	for _, e := range exprs {
		fmt.Printf("%s = %d\n", e, eval(e))
