import "fmt"

// graph is an adjacency list. Nodes are integers 0..n-1.
type graph [][]int

// hasCycle reports whether the directed graph contains a cycle.
func (g graph) hasCycle() bool {
	const (
		white = 0
		gray  = 1
		black = 2
	)
	color := make([]int, len(g))
	var dfs func(int) bool
	dfs = func(v int) bool {
		color[v] = gray
		for _, u := range g[v] {
			if color[u] == gray {
				return true
			}
			if color[u] == white && dfs(u) {
				return true
			}
		}
		color[v] = black
		return false
	}
	for v := range g {
		if color[v] == white && dfs(v) {
			return true
		}
	}
	return false
}

// topoSort returns a topological ordering of the graph.
// It assumes the graph is acyclic; if not, it returns nil.
func (g graph) topoSort() []int {
	const (
		white = 0
		gray  = 1
		black = 2
	)
	color := make([]int, len(g))
	order := make([]int, 0, len(g))
	var dfs func(int) bool
	dfs = func(v int) bool {
		color[v] = gray
		for _, u := range g[v] {
			if color[u] == gray {
				return false
			}
			if color[u] == white && !dfs(u) {
				return false
			}
		}
		color[v] = black
		order = append(order, v)
		return true
	}
	for v := range g {
		if color[v] == white && !dfs(v) {
			return nil
		}
	}
	// reverse the order to get topological sort
	for i, j := 0, len(order)-1; i < j; i, j = i+1, j-1 {
		order[i], order[j] = order[j], order[i]
	}
	return order
}

// longestPath returns the length of the longest path in the DAG.
// The path may start and end anywhere. It returns -1 if a cycle exists.
func (g graph) longestPath() int {
	if g.hasCycle() {
		return -1
	}
	topo := g.topoSort()
	if topo == nil {
		return -1
	}
	dist := make([]int, len(g))
	// Process nodes in topological order.
	// For each node, relax its outgoing edges.
	for _, v := range topo {
		for _, u := range g[v] {
			if dist[u] < dist[v]+1 {
				dist[u] = dist[v] + 1
			}
		}
	}
	max := 0
	for _, d := range dist {
		if d > max {
			max = d
		}
	}
	return max
}

func main() {
	// Example DAG: 0->1, 0->2, 1->3, 2->3
	g := graph{
		{1, 2},
		{3},
		{3},
		{},
	}
	fmt.Println("Longest path length:", g.longestPath()) // expect 2
	fmt.Println("Has cycle:", g.hasCycle())               // expect false
	// Add a cycle and test again
	g[3] = []int{0}
	fmt.Println("Longest path length with cycle:", g.longestPath()) // expect -1
	fmt.Println("Has cycle:", g.hasCycle())               // expect true
}

